/authStore.ts","../../src/stores/apiKeyAuthStore.ts"],"sourcesContent":["/**\n * FNV-1a hash function for creating short, deterministic keys from strings.\n *\n * Used to create 8-character hex keys from workflow paths for localStorage keys.\n * FNV-1a is chosen for its simplicity, speed, and good distribution properties.\n *\n * @param str - The string to hash (typically a workflow path)\n * @returns A 32-bit unsigned integer hash\n */\nexport function fnv1a(str: string): number {\n  let hash = 2166136261\n  for (let i = 0; i < str.length; i++) {\n    hash ^= str.charCodeAt(i)\n    hash = Math.imul(hash, 16777619)\n  }\n  return hash >>> 0\n}\n\n/**\n * Creates an 8-character hex key from a workflow path using FNV-1a hash.\n *\n * @param path - The workflow path (e.g., \"workflows/My Workflow.json\")\n * @returns An 8-character hex string (e.g., \"a1b2c3d4\")\n *\n * @example\n * hashPath(\"workflows/Untitled.json\") // \"1a2b3c4d\"\n */\nexport function hashPath(path: string): string {\n  return fnv1a(path).toString(16).padStart(8, '0')\n}\n","export const WORKSPACE_STORAGE_KEYS = {\n  // sessionStorage keys (cleared on browser close)\n  CURRENT_WORKSPACE: 'Comfy.Workspace.Current',\n  TOKEN: 'Comfy.Workspace.Token',\n  EXPIRES_AT: 'Comfy.Workspace.ExpiresAt',\n  OWNER_UID: 'Comfy.Workspace.OwnerUid',\n  SWITCH_TARGET_ID: 'Comfy.Workspace.SwitchTargetId',\n  // localStorage key (persists across browser sessions)\n  LAST_WORKSPACE_ID: 'Comfy.Workspace.LastWorkspaceId'\n} as const\n\nexport const TOKEN_REFRESH_BUFFER_MS = 5 * 60 * 1000\n\nexport const MAX_SCHEDULED_REFRESH_RETRIES = 3\n","import { WORKSPACE_STORAGE_KEYS } from '@/platform/workspace/workspaceConstants'\nimport { isCloud } from '@/platform/distribution/types'\n\nimport { hashPath } from './hashUtil'\n\n/**\n * Gets the current workspace ID from sessionStorage.\n * Returns 'personal' for personal workspace or when no workspace is set.\n *\n * NOTE: This is called fresh each time rather than cached at module load,\n * because the workspace auth store may not have set sessionStorage yet\n * when this module is first imported.\n */\nexport function getWorkspaceId(): string {\n  if (!isCloud) return 'personal'\n\n  try {\n    const json = sessionStorage.getItem(\n      WORKSPACE_STORAGE_KEYS.CURRENT_WORKSPACE\n    )\n    if (!json) return 'personal'\n\n    const workspace = JSON.parse(json)\n    if (workspace.type === 'personal' || !workspace.id) return 'personal'\n    return workspace.id\n  } catch {\n    return 'personal'\n  }\n}\n\n/**\n * Storage key generators for V2 workflow persistence.\n *\n * localStorage keys are scoped by workspaceId.\n * sessionStorage keys are scoped by clientId.\n */\nexport const StorageKeys = {\n  /**\n   * Draft index key for localStorage.\n   * Contains LRU order and metadata for all drafts.\n   */\n  draftIndex(workspaceId: string): string {\n    return `Comfy.Workflow.DraftIndex.v2:${workspaceId}`\n  },\n\n  /**\n   * Individual draft payload key for localStorage.\n   * @param path - Workflow path (will be hashed to create key)\n   */\n  draftPayload(path: string, workspaceId: string): string {\n    const draftKey = hashPath(path)\n    return `Comfy.Workflow.Draft.v2:${workspaceId}:${draftKey}`\n  },\n\n  /**\n   * Creates a draft key (hash) from a workflow path.\n   */\n  draftKey(path: string): string {\n    return hashPath(path)\n  },\n\n  /**\n   * Active workflow pointer key for sessionStorage.\n   * @param clientId - Browser tab identifier from api.clientId\n   */\n  activePath(clientId: string): string {\n    return `Comfy.Workflow.ActivePath:${clientId}`\n  },\n\n  /**\n   * Open workflows pointer key for sessionStorage.\n   * @param clientId - Browser tab identifier from api.clientId\n   */\n  openPaths(clientId: string): string {\n    return `Comfy.Workflow.OpenPaths:${clientId}`\n  },\n\n  agentThread(workspaceId: string): string {\n    return `Comfy.Agent.ThreadId:${workspaceId}`\n  },\n\n  agentWorkflowTabBindings(workspaceId: string): string {\n    return `Comfy.Agent.WorkflowTabBindings:${workspaceId}`\n  },\n\n  agentChatTitles(workspaceId: string): string {\n    return `Comfy.Agent.ChatTitles:${workspaceId}`\n  },\n\n  agentDeletedThreads(workspaceId: string): string {\n    return `Comfy.Agent.DeletedThreads:${workspaceId}`\n  },\n\n  /**\n   * localStorage copies of tab pointers for cross-session restore.\n   * sessionStorage is per-tab (correct for in-session use) but lost\n   * on browser restart; these keys preserve the last-written state.\n   */\n  lastActivePath(workspaceId: string): string {\n    return `Comfy.Workflow.LastActivePath:${workspaceId}`\n  },\n\n  lastOpenPaths(workspaceId: string): string {\n    return `Comfy.Workflow.LastOpenPaths:${workspaceId}`\n  },\n\n  /**\n   * Prefix patterns for cleanup operations.\n   */\n  prefixes: {\n    draftIndex: 'Comfy.Workflow.DraftIndex.v2:',\n    draftPayload: 'Comfy.Workflow.Draft.v2:',\n    activePath: 'Comfy.Workflow.ActivePath:',\n    openPaths: 'Comfy.Workflow.OpenPaths:',\n    lastActivePath: 'Comfy.Workflow.LastActivePath:',\n    lastOpenPaths: 'Comfy.Workflow.LastOpenPaths:',\n    agentThread: 'Comfy.Agent.ThreadId:',\n    agentWorkflowTabBindings: 'Comfy.Agent.WorkflowTabBindings:',\n    agentChatTitles: 'Comfy.Agent.ChatTitles:',\n    agentDeletedThreads: 'Comfy.Agent.DeletedThreads:'\n  }\n} as const\n","/**\n * V2 Storage I/O - localStorage read/write with error handling.\n *\n * Handles quota management, orphan cleanup, and graceful degradation.\n */\n\nimport type {\n  ActivePathPointer,\n  DraftIndexV2,\n  DraftPayloadV2,\n  OpenPathsPointer\n} from './draftTypes'\nimport { StorageKeys } from './storageKeys'\n\ntype StorageAvailability = 'available' | 'unavailable'\ntype WorkflowStorageState =\n  | { status: 'ready'; availability: StorageAvailability }\n  | {\n      status: 'transitioning'\n      reason: 'workspace'\n      resumeAvailability: StorageAvailability\n      ownerId: symbol\n    }\n  | {\n      status: 'transitioning'\n      reason: 'logout'\n      resumeAvailability: StorageAvailability\n    }\n\nlet workflowStorageState: WorkflowStorageState = {\n  status: 'ready',\n  availability: 'available'\n}\nconst pendingPersistenceFlushes = new Set<() => void>()\n\nexport function registerWorkflowPersistenceFlush(\n  flush: () => void\n): () => void {\n  pendingPersistenceFlushes.add(flush)\n  return () => pendingPersistenceFlushes.delete(flush)\n}\n\nfunction flushPendingWorkflowPersistence(): void {\n  for (const flush of pendingPersistenceFlushes) {\n    try {\n      flush()\n    } catch (error) {\n      console.warn('Failed to flush pending workflow persistence', error)\n    }\n  }\n}\n\nexport function isStorageAvailable(): boolean {\n  return (\n    workflowStorageState.status === 'ready' &&\n    workflowStorageState.availability === 'available'\n  )\n}\n\nexport function markStorageUnavailable(): void {\n  workflowStorageState =\n    workflowStorageState.status === 'transitioning'\n      ? { ...workflowStorageState, resumeAvailability: 'unavailable' }\n      : { status: 'ready', availability: 'unavailable' }\n}\n\nfunction isStorageReadable(): boolean {\n  return workflowStorageState.status === 'transitioning'\n    ? workflowStorageState.resumeAvailability === 'available'\n    : workflowStorageState.availability === 'available'\n}\n\n/** @internal Test-only: do not call from production code paths. */\nexport function resetStorageAvailable(): void {\n  workflowStorageState = { status: 'ready', availability: 'available' }\n}\n\nfunction isQuotaExceeded(error: unknown): boolean {\n  return (\n    error instanceof DOMException &&\n    (error.name === 'QuotaExceededError' ||\n      error.name === 'NS_ERROR_DOM_QUOTA_REACHED' ||\n      error.code === 22 ||\n      error.code === 1014)\n  )\n}\n\nfunction isValidIndex(value: unknown): value is DraftIndexV2 {\n  if (typeof value !== 'object' || value === null) return false\n  const obj = value as Record<string, unknown>\n  return (\n    obj.v === 2 &&\n    typeof obj.updatedAt === 'number' &&\n    Array.isArray(obj.order) &&\n    typeof obj.entries === 'object' &&\n    obj.entries !== null\n  )\n}\n\n/**\n * Reads and parses the draft index from localStorage.\n */\nexport function readIndex(workspaceId: string): DraftIndexV2 | null {\n  if (!isStorageReadable()) return null\n\n  try {\n    const key = StorageKeys.draftIndex(workspaceId)\n    const json = localStorage.getItem(key)\n    if (!json) return null\n\n    const parsed = JSON.parse(json)\n    if (!isValidIndex(parsed)) return null\n\n    return parsed\n  } catch {\n    return null\n  }\n}\n\n/**\n * Writes the draft index to localStorage.\n */\nexport function writeIndex(workspaceId: string, index: DraftIndexV2): boolean {\n  if (!isStorageAvailable()) return false\n\n  try {\n    const key = StorageKeys.draftIndex(workspaceId)\n    localStorage.setItem(key, JSON.stringify(index))\n    return true\n  } catch (error) {\n    if (isQuotaExceeded(error)) return false\n    throw error\n  }\n}\n\n/**\n * Reads a draft payload from localStorage.\n */\nexport function readPayload(\n  workspaceId: string,\n  draftKey: string\n): DraftPayloadV2 | null {\n  if (!isStorageReadable()) return null\n\n  try {\n    const key = `${StorageKeys.prefixes.draftPayload}${workspaceId}:${draftKey}`\n    const json = localStorage.getItem(key)\n    if (!json) return null\n\n    return JSON.parse(json) as DraftPayloadV2\n  } catch {\n    return null\n  }\n}\n\n/**\n * Writes a draft payload to localStorage.\n */\nexport function writePayload(\n  workspaceId: string,\n  draftKey: string,\n  payload: DraftPayloadV2\n): boolean {\n  if (!isStorageAvailable()) return false\n\n  try {\n    const key = `${StorageKeys.prefixes.draftPayload}${workspaceId}:${draftKey}`\n    localStorage.setItem(key, JSON.stringify(payload))\n    return true\n  } catch (error) {\n    if (isQuotaExceeded(error)) return false\n    throw error\n  }\n}\n\n/**\n * Deletes a draft payload from localStorage.\n */\nexport function deletePayload(workspaceId: string, draftKey: string): void {\n  try {\n    const key = `${StorageKeys.prefixes.draftPayload}${workspaceId}:${draftKey}`\n    localStorage.removeItem(key)\n  } catch {\n    // Ignore errors during deletion\n  }\n}\n\n/**\n * Deletes multiple draft payloads from localStorage.\n */\nexport function deletePayloads(workspaceId: string, draftKeys: string[]): void {\n  for (const draftKey of draftKeys) {\n    deletePayload(workspaceId, draftKey)\n  }\n}\n\n/**\n * Gets all draft payload keys for a workspace from localStorage.\n */\nexport function getPayloadKeys(workspaceId: string): string[] {\n  if (!isStorageReadable()) return []\n\n  const prefix = `${StorageKeys.prefixes.draftPayload}${workspaceId}:`\n  const keys: string[] = []\n\n  try {\n    for (let i = 0; i < localStorage.length; i++) {\n      const key = localStorage.key(i)\n      if (key?.startsWith(prefix)) {\n        keys.push(key.slice(prefix.length))\n      }\n    }\n  } catch {\n    return []\n  }\n\n  return keys\n}\n\n/**\n * Deletes orphan payloads that are not in the index.\n */\nexport function deleteOrphanPayloads(\n  workspaceId: string,\n  indexKeys: Set<string>\n): number {\n  const payloadKeys = getPayloadKeys(workspaceId)\n  let deleted = 0\n\n  for (const key of payloadKeys) {\n    if (!indexKeys.has(key)) {\n      deletePayload(workspaceId, key)\n      deleted++\n    }\n  }\n\n  return deleted\n}\n\n/**\n * Searches sessionStorage for a pointer matching the target workspaceId\n * when the exact clientId key has no entry (e.g. clientId changed after reload).\n * Migrates the found pointer to the new clientId key.\n */\nfunction findAndMigratePointer<T extends { workspaceId: string }>(\n  newKey: string,\n  prefix: string,\n  targetWorkspaceId: string,\n  isValid: (value: unknown) => value is T\n): T | null {\n  for (let i = 0; i < sessionStorage.length; i++) {\n    const storageKey = sessionStorage.key(i)\n    if (!storageKey?.startsWith(prefix) || storageKey === newKey) continue\n\n    const json = sessionStorage.getItem(storageKey)\n    if (!json) continue\n\n    try {\n      const pointer: unknown = JSON.parse(json)\n      if (isValid(pointer) && pointer.workspaceId === targetWorkspaceId) {\n        sessionStorage.setItem(newKey, json)\n        sessionStorage.removeItem(storageKey)\n        return pointer\n      }\n    } catch {\n      continue\n    }\n  }\n  return null\n}\n\n/**\n * Reads a session pointer by clientId with workspace-based fallback.\n * Validates workspace on exact match and removes stale cross-workspace pointers.\n * If no valid entry exists, searches for any pointer matching the target\n * workspaceId and migrates it to the new key.\n */\nfunction readSessionPointer<T extends { workspaceId: string }>(\n  key: string,\n  prefix: string,\n  targetWorkspaceId: string | undefined,\n  isValid: (value: unknown) => value is T\n): T | null {\n  try {\n    const json = sessionStorage.getItem(key)\n    if (json) {\n      const pointer: unknown = JSON.parse(json)\n      if (!isValid(pointer)) {\n        sessionStorage.removeItem(key)\n      } else if (\n        targetWorkspaceId &&\n        pointer.workspaceId !== targetWorkspaceId\n      ) {\n        sessionStorage.removeItem(key)\n      } else {\n        return pointer\n      }\n    }\n\n    if (targetWorkspaceId) {\n      return findAndMigratePointer(key, prefix, targetWorkspaceId, isValid)\n    }\n\n    return null\n  } catch {\n    return null\n  }\n}\n\n/**\n * Reads the active path pointer from sessionStorage.\n * Falls back to workspace-based search when clientId changes after reload,\n * then to localStorage when sessionStorage is empty (browser restart).\n */\nexport function readActivePath(\n  clientId: string,\n  targetWorkspaceId?: string\n): ActivePathPointer | null {\n  return (\n    readSessionPointer<ActivePathPointer>(\n      StorageKeys.activePath(clientId),\n      StorageKeys.prefixes.activePath,\n      targetWorkspaceId,\n      isValidActivePathPointer\n    ) ??\n    (targetWorkspaceId\n      ? readLocalPointer<ActivePathPointer>(\n          StorageKeys.lastActivePath(targetWorkspaceId),\n          isValidActivePathPointer\n        )\n      : null)\n  )\n}\n\n/**\n * Writes the active path pointer to both sessionStorage (tab-scoped)\n * and localStorage (survives browser restart).\n */\nexport function writeActivePath(\n  clientId: string,\n  pointer: ActivePathPointer\n): void {\n  const json = JSON.stringify(pointer)\n  writeStorage(sessionStorage, StorageKeys.activePath(clientId), json)\n  writeStorage(\n    localStorage,\n    StorageKeys.lastActivePath(pointer.workspaceId),\n    json\n  )\n}\n\n/** Inverse of {@link writeActivePath}: drops both pointers it writes. */\nexport function clearActivePath(clientId: string, workspaceId: string): void {\n  try {\n    sessionStorage.removeItem(StorageKeys.activePath(clientId))\n    localStorage.removeItem(StorageKeys.lastActivePath(workspaceId))\n  } catch {\n    // Storage access can throw in private-mode browsers; nothing to undo.\n  }\n}\n\n/**\n * Reads the open paths pointer from sessionStorage.\n * Falls back to workspace-based search when clientId changes after reload,\n * then to localStorage when sessionStorage is empty (browser restart).\n */\nexport function readOpenPaths(\n  clientId: string,\n  targetWorkspaceId?: string\n): OpenPathsPointer | null {\n  return (\n    readSessionPointer<OpenPathsPointer>(\n      StorageKeys.openPaths(clientId),\n      StorageKeys.prefixes.openPaths,\n      targetWorkspaceId,\n      isValidOpenPathsPointer\n    ) ??\n    (targetWorkspaceId\n      ? readLocalPointer<OpenPathsPointer>(\n          StorageKeys.lastOpenPaths(targetWorkspaceId),\n          isValidOpenPathsPointer\n        )\n      : null)\n  )\n}\n\n/**\n * Writes the open paths pointer to both sessionStorage (tab-scoped)\n * and localStorage (survives browser restart).\n */\nexport function writeOpenPaths(\n  clientId: string,\n  pointer: OpenPathsPointer\n): void {\n  const json = JSON.stringify(pointer)\n  writeStorage(sessionStorage, StorageKeys.openPaths(clientId), json)\n  writeStorage(\n    localStorage,\n    StorageKeys.lastOpenPaths(pointer.workspaceId),\n    json\n  )\n}\n\nfunction hasWorkspaceId(obj: Record<string, unknown>): boolean {\n  return typeof obj.workspaceId === 'string'\n}\n\nfunction isValidActivePathPointer(value: unknown): value is ActivePathPointer {\n  if (typeof value !== 'object' || value === null) return false\n  const obj = value as Record<string, unknown>\n  return hasWorkspaceId(obj) && typeof obj.path === 'string'\n}\n\nfunction isValidOpenPathsPointer(value: unknown): value is OpenPathsPointer {\n  if (typeof value !== 'object' || value === null) return false\n  const obj = value as Record<string, unknown>\n  return (\n    hasWorkspaceId(obj) &&\n    Array.isArray(obj.paths) &&\n    typeof obj.activeIndex === 'number'\n  )\n}\n\nfunction readLocalPointer<T>(\n  key: string,\n  validate: (value: unknown) => value is T\n): T | null {\n  try {\n    const json = localStorage.getItem(key)\n    if (!json) return null\n    const parsed = JSON.parse(json)\n    return validate(parsed) ? parsed : null\n  } catch {\n    return null\n  }\n}\n\nfunction writeStorage(storage: Storage, key: string, value: string): void {\n  if (!isStorageAvailable()) return\n\n  try {\n    storage.setItem(key, value)\n  } catch {\n    // Best effort — silently degrade when storage is full or unavailable\n  }\n}\n\nconst legacyLocalRestoreKeys = [\n  'Comfy.Workflow.Drafts',\n  'Comfy.Workflow.DraftOrder',\n  'Comfy.OpenWorkflowsPaths',\n  'Comfy.ActiveWorkflowIndex',\n  'Comfy.PreviousWorkflow',\n  'workflow'\n]\n\nconst legacyAgentKeys = [\n  'Comfy.Agent.ThreadId',\n  'Comfy.Agent.WorkflowTabBindings',\n  'Comfy.Agent.WorkflowTabBindings.v2',\n  'Comfy.Agent.ChatTitles',\n  'Comfy.Agent.DeletedThreads'\n]\n\nconst sessionRestorePrefixes = [\n  StorageKeys.prefixes.activePath,\n  StorageKeys.prefixes.openPaths,\n  'Comfy.PreviousWorkflow:',\n  'Comfy.OpenWorkflowsPaths:',\n  'Comfy.ActiveWorkflowIndex:',\n  'workflow:'\n]\n\nconst sessionRestoreKeys = [\n  'Comfy.PreviousWorkflow',\n  'Comfy.OpenWorkflowsPaths',\n  'Comfy.ActiveWorkflowIndex'\n]\n\nfunction removeStorageKeys(\n  storage: Storage,\n  keys: string[],\n  prefixes: string[] = []\n): void {\n  try {\n    for (let i = storage.length - 1; i >= 0; i--) {\n      const key = storage.key(i)\n      if (\n        key &&\n        (keys.includes(key) ||\n          prefixes.some((prefix) => key.startsWith(prefix)))\n      ) {\n        try {\n          storage.removeItem(key)\n        } catch {\n          continue\n        }\n      }\n    }\n  } catch {\n    return\n  }\n}\n\nexport function clearLegacyAgentStorage(): void {\n  removeStorageKeys(localStorage, legacyAgentKeys)\n}\n\nexport function clearWorkflowRestoreState(): void {\n  removeStorageKeys(localStorage, legacyLocalRestoreKeys)\n  removeStorageKeys(sessionStorage, sessionRestoreKeys, sessionRestorePrefixes)\n}\n\nexport function prepareWorkflowWorkspaceTransition(): () => void {\n  let ownerId: symbol | undefined\n  if (workflowStorageState.status === 'ready') {\n    flushPendingWorkflowPersistence()\n    ownerId = Symbol('workflow-storage-transition')\n    workflowStorageState = {\n      status: 'transitioning',\n      reason: 'workspace',\n      resumeAvailability: workflowStorageState.availability,\n      ownerId\n    }\n  }\n  clearWorkflowRestoreState()\n\n  return () => {\n    if (\n      workflowStorageState.status !== 'transitioning' ||\n      workflowStorageState.reason !== 'workspace' ||\n      workflowStorageState.ownerId !== ownerId\n    )\n      return\n\n    workflowStorageState = {\n      status: 'ready',\n      availability: workflowStorageState.resumeAvailability\n    }\n  }\n}\n\nexport function prepareWorkflowLogoutTransition(): void {\n  workflowStorageState = {\n    status: 'transitioning',\n    reason: 'logout',\n    resumeAvailability:\n      workflowStorageState.status === 'transitioning'\n        ? workflowStorageState.resumeAvailability\n        : workflowStorageState.availability\n  }\n}\n\nexport function completeWorkflowLogoutTransition(): void {\n  if (\n    workflowStorageState.status !== 'transitioning' ||\n    workflowStorageState.reason !== 'logout'\n  )\n    return\n\n  workflowStorageState = {\n    status: 'ready',\n    availability: workflowStorageState.resumeAvailability\n  }\n}\n\nexport function clearAllWorkflowStorage(): void {\n  const localPrefixes = [\n    StorageKeys.prefixes.draftIndex,\n    StorageKeys.prefixes.draftPayload,\n    StorageKeys.prefixes.lastActivePath,\n    StorageKeys.prefixes.lastOpenPaths,\n    'Comfy.Workflow.Drafts:',\n    'Comfy.Workflow.DraftOrder:'\n  ]\n\n  removeStorageKeys(localStorage, legacyLocalRestoreKeys, localPrefixes)\n  removeStorageKeys(sessionStorage, sessionRestoreKeys, sessionRestorePrefixes)\n}\n\nexport function clearAllWorkspaceStorage(): void {\n  clearAllWorkflowStorage()\n  clearLegacyAgentStorage()\n  removeStorageKeys(\n    localStorage,\n    [],\n    [\n      StorageKeys.prefixes.agentThread,\n      StorageKeys.prefixes.agentWorkflowTabBindings,\n      StorageKeys.prefixes.agentChatTitles,\n      StorageKeys.prefixes.agentDeletedThreads\n    ]\n  )\n}\n","/**\n * Self-healing for accounts whose customer record was never provisioned.\n *\n * Customer creation runs after the Firebase session is established during\n * sign-in/sign-up, so an interruption (navigation, closed tab, network\n * failure) can leave a permanently signed-in user without a customer\n * record. Sessions restored from persisted credentials never re-run the\n * sign-in flow, so every /customers/* request fails with 409 and nothing\n * ever retries the creation. The cloud app's rule, shared so every host\n * heals the same way.\n */\n\n/**\n * The auth middleware rejects requests for accounts without a customer\n * record using this exact message. Business-level 409s from /customers/*\n * endpoints (e.g. conflicting subscription state) must NOT trigger\n * provisioning or a blind retry of a payment request.\n */\nexport const MISSING_CUSTOMER_MESSAGE = 'Failed to find customer'\n\nexport async function isMissingCustomerResponse(\n  response: Response\n): Promise<boolean> {\n  if (response.status !== 409) return false\n  try {\n    const body: unknown = await response.clone().json()\n    return (\n      typeof body === 'object' &&\n      body !== null &&\n      'message' in body &&\n      body.message === MISSING_CUSTOMER_MESSAGE\n    )\n  } catch {\n    return false\n  }\n}\n\nexport function isCustomerEndpoint(input: string, base?: string): boolean {\n  try {\n    const { pathname } = new URL(input, base)\n    return pathname === '/customers' || pathname.startsWith('/customers/')\n  } catch {\n    return false\n  }\n}\n\nexport interface CustomerRecoveryDeps {\n  /** The request itself; run again, once, after a successful recovery. */\n  readonly request: () => Promise<Response>\n  /** Provisions the customer; the host deduplicates concurrent callers. */\n  readonly recoverMissingCustomer: () => Promise<void>\n  /**\n   * False once the signed-in identity is no longer the one that started the\n   * request: recovery and retry are then skipped and the 409 returned.\n   */\n  readonly identityUnchanged?: () => boolean\n}\n\n/**\n * On a missing-customer 409 this provisions the customer record and retries\n * the original request a single time. If recovery fails, the original 409\n * response is returned so callers surface their normal error handling.\n */\nasync function retryAfterCustomerRecovery(\n  response: Response,\n  deps: CustomerRecoveryDeps\n): Promise<Response> {\n  const {\n    request,\n    recoverMissingCustomer,\n    identityUnchanged = () => true\n  } = deps\n  if (!(await isMissingCustomerResponse(response)) || !identityUnchanged()) {\n    return response\n  }\n\n  try {\n    await recoverMissingCustomer()\n  } catch (error) {\n    console.warn(\n      'Customer provisioning during 409 recovery failed; returning original response',\n      error\n    )\n    return response\n  }\n\n  if (!identityUnchanged()) {\n    return response\n  }\n\n  try {\n    return await request()\n  } catch (error) {\n    console.warn(\n      'Retry after customer provisioning failed; returning original 409 response',\n      error\n    )\n    return response\n  }\n}\n\n/**\n * The recovery above, applied only to /customers/* endpoints: a 409 from\n * anywhere else is never a missing customer.\n */\nexport async function fetchWithCustomerRecovery(\n  input: string,\n  deps: CustomerRecoveryDeps & {\n    /** Resolves a relative `input`; a browser host passes its page href. */\n    readonly base?: string\n  }\n): Promise<Response> {\n  const response = await deps.request()\n  if (!isCustomerEndpoint(input, deps.base)) return response\n  return retryAfterCustomerRecovery(response, deps)\n}\n","/**\n * The account-creation sequences both hosts must agree on, with the effects\n * injected so the invariants live (and are tested) exactly once. Mirrors the\n * platform app's `authStore.register` / `loginWithGoogle` semantics.\n */\n\ninterface DeletableUserCredential {\n  user: { delete: () => Promise<void> }\n}\n\n/**\n * Email sign-up: create the Firebase user, then provision the Comfy customer.\n *\n * Provisioning is where a Turnstile token gets validated server-side; if it\n * fails (rejection, 5xx, network) the Firebase user is already created and,\n * without rollback, the account is orphaned — every retry then fails\n * \"email already in use\", permanently bricking signup. So a provisioning\n * failure deletes the just-created user (best-effort with one retried\n * delete, so a single transient blip cannot orphan the account; a cleanup\n * failure never masks the original error) and rethrows.\n */\nexport async function signUpWithProvisioning<\n  T extends DeletableUserCredential\n>(deps: {\n  createUser: () => Promise<T>\n  provisionCustomer: (credential: T) => Promise<unknown>\n  onRollbackFailure?: (error: unknown) => void\n}): Promise<T> {\n  const credential = await deps.createUser()\n  try {\n    await deps.provisionCustomer(credential)\n  } catch (error) {\n    try {\n      try {\n        await credential.user.delete()\n      } catch {\n        await credential.user.delete()\n      }\n    } catch (rollbackError) {\n      // A reporting sink can throw; never let it displace the original error.\n      try {\n        deps.onRollbackFailure?.(rollbackError)\n      } catch {\n        void 0\n      }\n    }\n    throw error\n  }\n  return credential\n}\n\n/**\n * Social sign-in: the popup, then find-or-create the Comfy customer — always,\n * because a social user's first touch may be this host and skipping the\n * customer record produces accounts where billing surfaces fail.\n * `provisionCustomer` must tolerate an already-provisioned account. No\n * rollback here: the signed-in user may be a long-standing account, and\n * deleting it over a provisioning hiccup would destroy it — a provisioning\n * failure propagates with the user still signed in.\n */\nexport async function socialSignInWithProvisioning<T>(deps: {\n  signIn: () => Promise<T>\n  provisionCustomer: (credential: T) => Promise<unknown>\n}): Promise<T> {\n  const credential = await deps.signIn()\n  await deps.provisionCustomer(credential)\n  return credential\n}\n\nexport const CUSTOMER_PROVISIONING_PATH = '/customers'\n\n/**\n * The `POST /customers` request both hosts send. `signupSource` names the\n * host for the backend's attribution; the Turnstile token rides along only\n * on email sign-up, where the server validates it. Body and headers only: a\n * host that wants a bound passes its own `signal`.\n */\nexport function customerProvisioningRequest(options: {\n  authHeaders: Record<string, string>\n  signupSource: string\n  turnstileToken?: string\n  signal?: AbortSignal\n}): RequestInit {\n  const { authHeaders, signupSource, turnstileToken, signal } = options\n  return {\n    method: 'POST',\n    headers: { ...authHeaders, 'Content-Type': 'application/json' },\n    body: JSON.stringify({\n      signup_source: signupSource,\n      ...(turnstileToken ? { turnstile_token: turnstileToken } : {})\n    }),\n    ...(signal ? { signal } : {})\n  }\n}\n","import type { ExchangeTokenRequest } from '@comfyorg/ingest-types'\nimport {\n  zErrorResponse,\n  zExchangeTokenResponse\n} from '@comfyorg/ingest-types/zod'\n\nimport { reportError } from '@/platform/telemetry/reportError'\n\nconst PARTNER_NODE_RESOURCE = 'partner-node'\n\n/**\n * Ingest route that revokes partner-node sessions. A sign-in credential\n * revokes every session of that login, including ones an earlier page load\n * minted; a partner-node token (even expired) revokes only its own session.\n */\nconst PARTNER_NODE_REVOKE_ROUTE = '/auth/token/revoke'\n\n/** An ingest that predates sign-in revoke refuses the sign-in with this code. */\nconst SIGN_IN_REVOKE_UNSUPPORTED = 'auth_type_not_allowed'\n\n/** A cached token is reused only while it has at least this much life left. */\nexport const PARTNER_NODE_REUSE_MIN_REMAINING_MS = 60 * 60 * 1000\n\ntype PartnerNodeMintRequest = ExchangeTokenRequest & {\n  workspace_id: string\n  resource: typeof PARTNER_NODE_RESOURCE\n}\n\nconst zPartnerNodeTokenResponse = zExchangeTokenResponse.pick({\n  token: true,\n  expires_at: true,\n  workspace: true\n})\n\nexport interface PartnerNodeTokenTarget {\n  ownerUid: string\n  workspaceId: string\n  /** Mint bearer: a Firebase ID token or a host OAuth access token. */\n  credential: () => Promise<string | undefined>\n}\n\ninterface PartnerNodeTokenSourceDeps {\n  apiUrl: (route: string) => string\n  now?: () => number\n}\n\ninterface MintedPartnerNodeToken {\n  ownerUid: string\n  token: string\n  expiresAt: number\n}\n\ntype MintFailureReason =\n  | 'no_identity'\n  | 'network'\n  | 'http'\n  | 'malformed'\n  | 'workspace_mismatch'\n  | 'expired'\n\ntype RevokeOutcome =\n  | { ok: true }\n  | { ok: false; reason: 'network' }\n  | { ok: false; reason: 'http'; status: number; code?: string }\n\ntype MintOutcome =\n  | { ok: true; token: string; expiresAt: number }\n  | { ok: false; reason: MintFailureReason; status?: number }\n\nexport function createPartnerNodeTokenSource({\n  apiUrl,\n  now = () => Date.now()\n}: PartnerNodeTokenSourceDeps) {\n  const minted = new Map<string, MintedPartnerNodeToken>()\n  const inFlight = new Map<string, Promise<string | undefined>>()\n  let generation = 0\n\n  const keyOf = ({ ownerUid, workspaceId }: PartnerNodeTokenTarget) =>\n    `${ownerUid}:${workspaceId}`\n\n  async function mint(target: PartnerNodeTokenTarget): Promise<MintOutcome> {\n    const credential = await target.credential()\n    if (!credential) return { ok: false, reason: 'no_identity' }\n\n    const body: PartnerNodeMintRequest = {\n      workspace_id: target.workspaceId,\n      resource: PARTNER_NODE_RESOURCE\n    }\n    let response: Response\n    try {\n      response = await fetch(apiUrl('/auth/token'), {\n        method: 'POST',\n        headers: {\n          Authorization: `Bearer ${credential}`,\n          'Content-Type': 'application/json'\n        },\n        body: JSON.stringify(body)\n      })\n    } catch {\n      return { ok: false, reason: 'network' }\n    }\n    if (!response.ok) {\n      return { ok: false, reason: 'http', status: response.status }\n    }\n\n    let json: unknown\n    try {\n      json = await response.json()\n    } catch {\n      return { ok: false, reason: 'malformed' }\n    }\n    const parsed = zPartnerNodeTokenResponse.safeParse(json)\n    if (!parsed.success) return { ok: false, reason: 'malformed' }\n    if (parsed.data.workspace.id !== target.workspaceId) {\n      return { ok: false, reason: 'workspace_mismatch' }\n    }\n    const expiresAt = Date.parse(parsed.data.expires_at)\n    if (!(expiresAt > now())) return { ok: false, reason: 'expired' }\n    return { ok: true, token: parsed.data.token, expiresAt }\n  }\n\n  async function requestRevoke(bearer: string): Promise<RevokeOutcome> {\n    let response: Response\n    try {\n      response = await fetch(apiUrl(PARTNER_NODE_REVOKE_ROUTE), {\n        method: 'POST',\n        headers: { Authorization: `Bearer ${bearer}` }\n      })\n    } catch {\n      return { ok: false, reason: 'network' }\n    }\n    if (response.ok) return { ok: true }\n    const body: unknown = await response.json().catch(() => undefined)\n    const code = zErrorResponse.safeParse(body).data?.code\n    return { ok: false, reason: 'http', status: response.status, code }\n  }\n\n  function reportRevokeFailure(\n    outcome: Exclude<RevokeOutcome, { ok: true }>\n  ): void {\n    reportError(new Error('Partner-node session revoke failed'), {\n      surface: 'auth',\n      errorType: 'failure_revoking_partner_node_sessions',\n      level: 'warning',\n      tags:\n        outcome.reason === 'http'\n          ? { reason: outcome.reason, status: outcome.status }\n          : { reason: outcome.reason }\n    })\n  }\n\n  async function revokeWith(token: string): Promise<void> {\n    const outcome = await requestRevoke(token)\n    if (!outcome.ok) reportRevokeFailure(outcome)\n  }\n\n  /** Forgets every minted token, returning one held token per account. */\n  function forgetAll(): string[] {\n    generation += 1\n    inFlight.clear()\n    const tokenPerOwner = new Map<string, string>()\n    for (const { ownerUid, token } of minted.values()) {\n      tokenPerOwner.set(ownerUid, token)\n    }\n    minted.clear()\n    return [...tokenPerOwner.values()]\n  }\n\n  function reusableToken(key: string): string | undefined {\n    const entry = minted.get(key)\n    if (!entry) return undefined\n    return entry.expiresAt - now() > PARTNER_NODE_REUSE_MIN_REMAINING_MS\n      ? entry.token\n      : undefined\n  }\n\n  /**\n   * A partner-node token for the target, reused while it has comfortable life\n   * left, minted once for concurrent callers. Undefined when minting failed,\n   * so the caller keeps the workspace token.\n   */\n  function tokenFor(\n    target: PartnerNodeTokenTarget\n  ): Promise<string | undefined> {\n    const key = keyOf(target)\n    const reusable = reusableToken(key)\n    if (reusable) return Promise.resolve(reusable)\n    const pending = inFlight.get(key)\n    if (pending) return pending\n\n    const mintGeneration = generation\n    const request = mint(target).then((outcome) => {\n      if (!outcome.ok) {\n        reportError(new Error('Partner-node token mint failed'), {\n          surface: 'auth',\n          errorType: 'failure_minting_partner_node_token',\n          level: 'warning',\n          tags: { reason: outcome.reason, status: outcome.status }\n        })\n        return undefined\n      }\n      if (mintGeneration !== generation) {\n        void revokeWith(outcome.token)\n        return undefined\n      }\n      minted.set(key, {\n        ownerUid: target.ownerUid,\n        token: outcome.token,\n        expiresAt: outcome.expiresAt\n      })\n      return outcome.token\n    })\n    inFlight.set(key, request)\n    void request.finally(() => {\n      if (inFlight.get(key) === request) inFlight.delete(key)\n    })\n    return request\n  }\n\n  /**\n   * Forgets every minted token and revokes with the ones this page load still\n   * holds. Used when the sign-in credential is already gone.\n   */\n  async function revokeAll(): Promise<void> {\n    await Promise.all(forgetAll().map(revokeWith))\n  }\n\n  /**\n   * Forgets every minted token and revokes every partner-node session of the\n   * login `credential` signed in, whichever page load minted them. Falls back\n   * to the held tokens when there is no credential or the ingest does not\n   * take a sign-in on this route yet.\n   */\n  async function revokeLogin(credential: string | undefined): Promise<void> {\n    const held = forgetAll()\n    if (credential) {\n      const outcome = await requestRevoke(credential)\n      if (outcome.ok) return\n      const signInUnsupported =\n        outcome.reason === 'http' && outcome.code === SIGN_IN_REVOKE_UNSUPPORTED\n      if (!signInUnsupported) {\n        reportRevokeFailure(outcome)\n        return\n      }\n    }\n    await Promise.all(held.map(revokeWith))\n  }\n\n  return { tokenFor, revokeAll, revokeLogin }\n}\n","import { getComfyCloudBaseUrl } from '@/config/comfyApi'\nimport { isCloud } from '@/platform/distribution/types'\nimport { api } from '@/scripts/api'\n\nexport function workspaceApiUrl(route: string): string {\n  return isCloud ? api.apiURL(route) : `${getComfyCloudBaseUrl()}/api${route}`\n}\n","import { createPartnerNodeTokenSource } from '@/platform/auth/partnerNode/partnerNodeTokenSource'\nimport { workspaceApiUrl } from '@/platform/workspace/api/workspaceApiUrl'\n\nexport const partnerNodeTokens = createPartnerNodeTokenSource({\n  apiUrl: workspaceApiUrl\n})\n","/**\n * The session-backed identity source: boots a site from `GET /auth/session`\n * and follows the server's answer. It keeps no record of past sessions, and\n * the remembered provider login is an opaque port, so no provider leaks in.\n */\nimport { z } from 'zod'\n\nimport type {\n  CrossTabRefreshPort,\n  WebSession,\n  WebSessionCommandResult,\n  WebSessionFailure,\n  WebSessionResult\n} from './sessionContracts.js'\nimport type { WebSessionOptions } from './webSession.js'\nimport {\n  createWebSession,\n  deleteWebSession,\n  readWebSession\n} from './webSession.js'\n\nexport interface RememberedLogin {\n  /** The Comfy user id of the login this browser remembers, or null. */\n  currentUserId: () => Promise<string | null>\n  /** Null when the provider has no usable login; a throw is transient. */\n  getProof: () => Promise<string | null>\n  signOutLocally: () => Promise<void>\n}\n\nexport type WebSessionPrincipal =\n  | { readonly kind: 'account'; readonly rememberedLogin: RememberedLogin }\n  | { readonly kind: 'api_key' }\n\nexport type WebSessionBootOutcome =\n  | 'signed_in'\n  | 'restored'\n  | 'signed_out'\n  | 'revoked'\n  | 'restore_failed'\n\nexport interface WebSessionBootstrapEvent {\n  readonly outcome: WebSessionBootOutcome\n  readonly origin: string\n}\n\ntype SignedOutOutcome = Exclude<WebSessionBootOutcome, 'signed_in' | 'restored'>\n\n/** The account this tab holds changed under it, or went away. */\nexport type WebSessionAccountChange =\n  | { readonly reason: 'user_changed'; readonly session: WebSession }\n  | { readonly reason: 'signed_out'; readonly outcome: SignedOutOutcome }\n\nexport type WebSessionIdentityState =\n  | { readonly phase: 'idle' }\n  | { readonly phase: 'api_key' }\n  | {\n      readonly phase: 'reading' | 'retry_wait' | 'restoring'\n      readonly failures: number\n    }\n  | { readonly phase: 'signed_in'; readonly session: WebSession }\n  | { readonly phase: 'signed_out'; readonly outcome: SignedOutOutcome }\n\n/** Only a sibling's sign-in is news to a tab that has signed out. */\nexport type SessionObservedFrom =\n  | 'this_tab'\n  | 'sibling_heartbeat'\n  | 'sibling_sign_in'\n  | 'sibling_sign_out'\n\nexport type WebSessionIdentityEvent =\n  | { readonly type: 'boot' }\n  | {\n      readonly type: 'read_answered' | 'restore_answered'\n      readonly result: WebSessionResult\n      readonly rememberedUserId: string | null\n    }\n  | { readonly type: 'proof_missing' | 'proof_errored' | 'login_errored' }\n  | { readonly type: 'retry_due' }\n  /** A heartbeat answer, this tab's or one a sibling tab published. */\n  | {\n      readonly type: 'session_observed'\n      readonly from: SessionObservedFrom\n      readonly result: WebSessionResult\n      readonly rememberedUserId: string | null\n    }\n  | { readonly type: 'session_created'; readonly session: WebSession }\n  | { readonly type: 'sign_out_requested' }\n\nexport type WebSessionIdentityEffect =\n  | { readonly type: 'read' }\n  | { readonly type: 'restore'; readonly expectedUserId: string }\n  | { readonly type: 'schedule_retry'; readonly failures: number }\n  | { readonly type: 'sign_out_locally' }\n  | { readonly type: 'report'; readonly outcome: WebSessionBootOutcome }\n  | {\n      readonly type: 'account_changed'\n      readonly change: WebSessionAccountChange\n    }\n  | { readonly type: 'report_signed_out_remotely' }\n\nexport interface WebSessionIdentityTransition {\n  readonly state: WebSessionIdentityState\n  readonly effects: readonly WebSessionIdentityEffect[]\n}\n\nconst read: WebSessionIdentityEffect = { type: 'read' }\nconst signOutLocally: WebSessionIdentityEffect = { type: 'sign_out_locally' }\n\nfunction signOutDifferentLogin(\n  session: WebSession,\n  rememberedUserId: string | null\n): WebSessionIdentityEffect[] {\n  return rememberedUserId !== null && rememberedUserId !== session.user.id\n    ? [signOutLocally]\n    : []\n}\n\nfunction settleSignedIn(\n  session: WebSession,\n  rememberedUserId: string | null,\n  outcome: 'signed_in' | 'restored'\n): WebSessionIdentityTransition {\n  return {\n    state: { phase: 'signed_in', session },\n    effects: [\n      ...signOutDifferentLogin(session, rememberedUserId),\n      { type: 'report', outcome }\n    ]\n  }\n}\n\nfunction settleSignedOut(\n  outcome: SignedOutOutcome\n): WebSessionIdentityTransition {\n  return {\n    state: { phase: 'signed_out', outcome },\n    effects: [\n      ...(outcome === 'revoked' ? [signOutLocally] : []),\n      { type: 'report', outcome }\n    ]\n  }\n}\n\nfunction waitToRetry(failures: number): WebSessionIdentityTransition {\n  return {\n    state: { phase: 'retry_wait', failures },\n    effects: [{ type: 'schedule_retry', failures }]\n  }\n}\n\nfunction isNoLiveSession(failure: WebSessionFailure): boolean {\n  return failure.code === 'NO_SESSION' || failure.code === 'SESSION_EXPIRED'\n}\n\nfunction applyReadAnswered(\n  failures: number,\n  result: WebSessionResult,\n  rememberedUserId: string | null\n): WebSessionIdentityTransition {\n  if (result.status === 'ok') {\n    return settleSignedIn(result.session, rememberedUserId, 'signed_in')\n  }\n  if (result.retryable) return waitToRetry(failures + 1)\n  if (result.code === 'SESSION_REVOKED') return settleSignedOut('revoked')\n  if (!isNoLiveSession(result)) return settleSignedOut('signed_out')\n  if (rememberedUserId === null) return settleSignedOut('signed_out')\n  return {\n    state: { phase: 'restoring', failures },\n    effects: [{ type: 'restore', expectedUserId: rememberedUserId }]\n  }\n}\n\nfunction applyRestoreAnswered(\n  failures: number,\n  result: WebSessionResult,\n  rememberedUserId: string | null\n): WebSessionIdentityTransition {\n  if (result.status === 'ok') {\n    return settleSignedIn(result.session, rememberedUserId, 'restored')\n  }\n  if (result.retryable) return waitToRetry(failures + 1)\n  if (result.code === 'SESSION_REVOKED') return settleSignedOut('revoked')\n  return settleSignedOut('restore_failed')\n}\n\nfunction leaveAccount(\n  outcome: SignedOutOutcome,\n  effects: readonly WebSessionIdentityEffect[] = []\n): WebSessionIdentityTransition {\n  return {\n    state: { phase: 'signed_out', outcome },\n    effects: [\n      ...effects,\n      { type: 'account_changed', change: { reason: 'signed_out', outcome } }\n    ]\n  }\n}\n\nfunction replaceSession(\n  held: WebSession,\n  session: WebSession,\n  effects: readonly WebSessionIdentityEffect[] = []\n): WebSessionIdentityTransition {\n  const state: WebSessionIdentityState = { phase: 'signed_in', session }\n  if (session.user.id === held.user.id) return { state, effects: [] }\n  return {\n    state,\n    effects: [\n      ...effects,\n      { type: 'account_changed', change: { reason: 'user_changed', session } }\n    ]\n  }\n}\n\n/** A read never signs out on doubt: only revoked or no live session does. */\nfunction observeWhileSignedIn(\n  state: Extract<WebSessionIdentityState, { phase: 'signed_in' }>,\n  result: WebSessionResult,\n  rememberedUserId: string | null,\n  restored: boolean,\n  ownRead: boolean\n): WebSessionIdentityTransition {\n  if (result.status === 'ok') {\n    return replaceSession(\n      state.session,\n      result.session,\n      signOutDifferentLogin(result.session, rememberedUserId)\n    )\n  }\n  if (result.retryable) return { state, effects: [] }\n  if (result.code === 'SESSION_REVOKED') {\n    return leaveAccount(\n      'revoked',\n      ownRead\n        ? [signOutLocally, { type: 'report_signed_out_remotely' }]\n        : [signOutLocally]\n    )\n  }\n  if (restored) return leaveAccount('restore_failed')\n  if (!isNoLiveSession(result)) return { state, effects: [] }\n  if (rememberedUserId === null) return leaveAccount('signed_out')\n  return {\n    state,\n    effects: [{ type: 'restore', expectedUserId: rememberedUserId }]\n  }\n}\n\nfunction transitionSignedIn(\n  state: Extract<WebSessionIdentityState, { phase: 'signed_in' }>,\n  event: WebSessionIdentityEvent\n): WebSessionIdentityTransition {\n  switch (event.type) {\n    case 'session_observed':\n      return observeWhileSignedIn(\n        state,\n        event.result,\n        event.rememberedUserId,\n        false,\n        event.from === 'this_tab'\n      )\n    case 'restore_answered':\n      return observeWhileSignedIn(\n        state,\n        event.result,\n        event.rememberedUserId,\n        true,\n        true\n      )\n    case 'session_created':\n      return replaceSession(state.session, event.session)\n    case 'proof_missing':\n      return leaveAccount('restore_failed')\n    case 'sign_out_requested':\n      return leaveAccount('signed_out', [signOutLocally])\n    default:\n      return { state, effects: [] }\n  }\n}\n\ntype SettlingState = Exclude<\n  WebSessionIdentityState,\n  { readonly phase: 'idle' | 'api_key' | 'signed_in' }\n>\n\nfunction transitionRestoring(\n  state: Extract<SettlingState, { readonly failures: number }>,\n  event: WebSessionIdentityEvent\n): WebSessionIdentityTransition {\n  switch (event.type) {\n    case 'restore_answered':\n      return applyRestoreAnswered(\n        state.failures,\n        event.result,\n        event.rememberedUserId\n      )\n    case 'proof_missing':\n      return settleSignedOut('restore_failed')\n    case 'proof_errored':\n    case 'login_errored':\n      return waitToRetry(state.failures + 1)\n    default:\n      return { state, effects: [] }\n  }\n}\n\nfunction transitionBoot(\n  state: SettlingState,\n  event: WebSessionIdentityEvent\n): WebSessionIdentityTransition {\n  switch (state.phase) {\n    case 'reading':\n      if (event.type === 'login_errored') return waitToRetry(state.failures + 1)\n      return event.type === 'read_answered'\n        ? applyReadAnswered(\n            state.failures,\n            event.result,\n            event.rememberedUserId\n          )\n        : { state, effects: [] }\n    case 'retry_wait':\n      return event.type === 'retry_due'\n        ? { state: { ...state, phase: 'reading' }, effects: [read] }\n        : { state, effects: [] }\n    case 'restoring':\n      return transitionRestoring(state, event)\n    default:\n      return { state, effects: [] }\n  }\n}\n\nfunction transitionSettling(\n  state: SettlingState,\n  event: WebSessionIdentityEvent\n): WebSessionIdentityTransition {\n  switch (event.type) {\n    case 'session_observed': {\n      const { result } = event\n      const adoptable =\n        state.phase === 'retry_wait' ||\n        (state.phase === 'signed_out' && event.from === 'sibling_sign_in')\n      if (result.status !== 'ok' || !adoptable) return { state, effects: [] }\n      return {\n        state: { phase: 'signed_in', session: result.session },\n        effects: signOutDifferentLogin(result.session, event.rememberedUserId)\n      }\n    }\n    case 'session_created':\n      return {\n        state: { phase: 'signed_in', session: event.session },\n        effects: []\n      }\n    case 'sign_out_requested':\n      return state.phase === 'signed_out'\n        ? { state, effects: [] }\n        : {\n            state: { phase: 'signed_out', outcome: 'signed_out' },\n            effects: [signOutLocally]\n          }\n    default:\n      return transitionBoot(state, event)\n  }\n}\n\n/** Pure: an event that means nothing in the current phase changes nothing. */\nexport function transitionWebSessionIdentity(\n  state: WebSessionIdentityState,\n  event: WebSessionIdentityEvent\n): WebSessionIdentityTransition {\n  switch (state.phase) {\n    case 'idle':\n      return event.type === 'boot'\n        ? { state: { phase: 'reading', failures: 0 }, effects: [read] }\n        : { state, effects: [] }\n    case 'api_key':\n      return { state, effects: [] }\n    case 'signed_in':\n      return transitionSignedIn(state, event)\n    default:\n      return transitionSettling(state, event)\n  }\n}\n\nexport type ScheduleRetry = (run: () => void, delayMs: number) => () => void\n\nexport interface VisibilityPort {\n  isVisible: () => boolean\n  onChange: (listener: (visible: boolean) => void) => () => void\n}\n\nexport interface WebSessionHeartbeatOptions {\n  readonly visibility: VisibilityPort\n  /** Without it every tab reads for itself. */\n  readonly crossTab?: CrossTabRefreshPort<WebSessionSharedMessage>\n  readonly intervalMs?: number\n}\n\nexport interface WebSessionIdentityOptions {\n  readonly session: WebSessionOptions\n  readonly principal: WebSessionPrincipal\n  /** The site reporting the boot, e.g. `https://www.comfy.org`. */\n  readonly origin: string\n  readonly onBootstrap?: (event: WebSessionBootstrapEvent) => void\n  /** Telemetry for `session_signed_out_remotely`. */\n  readonly onSignedOutRemotely?: (event: { readonly origin: string }) => void\n  /** The host drops pending actions and user-scoped state here. */\n  readonly onAccountChanged?: (\n    change: WebSessionAccountChange & { readonly epoch: number }\n  ) => void\n  readonly heartbeat?: WebSessionHeartbeatOptions\n  readonly schedule?: ScheduleRetry\n  readonly retryBaseMs?: number\n  readonly retryMaxMs?: number\n}\n\nexport interface WebSessionIdentity {\n  getState: () => WebSessionIdentityState\n  /** Delivers the current state at once, then every change. */\n  subscribe: (listener: (state: WebSessionIdentityState) => void) => () => void\n  /** Starts the boot and the heartbeat; a no-op unless idle. */\n  boot: () => void\n  /** Only after an interactive sign-in; a token refresh must never call it. */\n  signedIn: (getProof: () => Promise<string>) => Promise<WebSessionResult>\n  signOut: () => Promise<WebSessionCommandResult>\n  /**\n   * Reads the session now, as a heartbeat would, and resolves once the answer\n   * and any restore it starts have settled. Reads nothing unless signed in as\n   * `expectedUserId` (any user when omitted).\n   */\n  refresh: (expectedUserId?: string) => Promise<WebSessionIdentityState>\n  /** Changes with the account; an answer started under an older epoch is stale. */\n  getEpoch: () => number\n  /** Cancels timers, ignores answers in flight, and returns to idle. */\n  dispose: () => void\n}\n\nconst HEARTBEAT_KEY = '@comfyorg/account-core web-session heartbeat'\nconst HEARTBEAT_INTERVAL_MS = 10 * 60 * 1000\n\nconst zSharedResult = z.discriminatedUnion('status', [\n  z.object({\n    status: z.literal('ok'),\n    session: z.object({\n      user: z.object({\n        id: z.string(),\n        email: z.string(),\n        name: z.string().optional(),\n        emailVerified: z.boolean(),\n        signInProvider: z.string().optional(),\n        hasPersonalWorkspace: z.boolean().optional()\n      }),\n      csrfToken: z.string(),\n      expiresAt: z.number(),\n      absoluteExpiresAt: z.number()\n    })\n  }),\n  z.object({\n    status: z.literal('error'),\n    code: z.literal('SESSION_REVOKED'),\n    retryable: z.literal(false)\n  })\n])\n\n/**\n * Every tab of a site reads the same host-only cookie, so a sibling's answer\n * is this tab's own session observed elsewhere; that is what makes adopting\n * it safe. A per-tab session scope would break this assumption.\n */\nconst zSharedMessage = z.object({\n  from: z.enum(['heartbeat', 'sign_in', 'sign_out']),\n  result: zSharedResult\n})\n\ntype SharedFrom = z.infer<typeof zSharedMessage>['from']\n\n/** What one tab of a site tells its siblings, and why. */\nexport interface WebSessionSharedMessage {\n  readonly from: SharedFrom\n  readonly result: WebSessionResult\n}\n\nconst revoked: WebSessionResult = {\n  status: 'error',\n  code: 'SESSION_REVOKED',\n  retryable: false\n}\n\nconst scheduleWithTimer: ScheduleRetry = (run, delayMs) => {\n  const timer = setTimeout(run, delayMs)\n  return () => clearTimeout(timer)\n}\n\nfunction reportLocalSignOutFailure(error: unknown): void {\n  console.warn('webSessionIdentity: local sign-out failed', error)\n}\n\nfunction createApiKeyIdentity(): WebSessionIdentity {\n  const state: WebSessionIdentityState = { phase: 'api_key' }\n  return {\n    getState: () => state,\n    subscribe: (listener) => {\n      listener(state)\n      return () => undefined\n    },\n    boot: () => undefined,\n    signedIn: async () => ({\n      status: 'error',\n      code: 'SESSION_REQUEST_REFUSED',\n      retryable: false\n    }),\n    signOut: async () => ({ status: 'ok' }),\n    refresh: async () => state,\n    getEpoch: () => 0,\n    dispose: () => undefined\n  }\n}\n\nfunction createAccountIdentity(\n  options: WebSessionIdentityOptions,\n  login: RememberedLogin\n): WebSessionIdentity {\n  const schedule = options.schedule ?? scheduleWithTimer\n  const retryBaseMs = options.retryBaseMs ?? 1000\n  const retryMaxMs = options.retryMaxMs ?? 60_000\n  const heartbeat = options.heartbeat\n  const listeners = new Set<(state: WebSessionIdentityState) => void>()\n  let state: WebSessionIdentityState = { phase: 'idle' }\n  let epoch = 0\n  let signOuts = 0\n  let signIns = 0\n  let liveSignIn = 0\n  let cancelRetry: (() => void) | undefined\n  let cancelBeat: (() => void) | undefined\n  let releaseLeadership: (() => void) | undefined\n  let stopWatching: (() => void)[] = []\n  let restoring = { epoch, settled: Promise.resolve() }\n\n  function dispatch(event: WebSessionIdentityEvent): void {\n    const next = transitionWebSessionIdentity(state, event)\n    const changed = next.state !== state\n    state = next.state\n    next.effects.forEach(run)\n    if (changed) listeners.forEach((listener) => listener(state))\n    syncLeadership()\n  }\n\n  function publish(from: SharedFrom, result: WebSessionResult): void {\n    heartbeat?.crossTab?.publishCredential(HEARTBEAT_KEY, { from, result })\n  }\n\n  type Answered =\n    | { readonly type: 'read_answered' | 'restore_answered' }\n    | { readonly type: 'session_observed'; readonly from: SessionObservedFrom }\n\n  async function answer(\n    started: number,\n    answered: Answered,\n    request: () => Promise<WebSessionResult>\n  ): Promise<void> {\n    const result = await request()\n    const remembered = await login.currentUserId().then(\n      (value) => ({ value }),\n      () => undefined\n    )\n    if (started !== epoch) return\n    // A failed lookup matters only without a live session to adopt: with one,\n    // it can skip nothing but the different-user sign-out.\n    if (remembered === undefined && result.status !== 'ok') {\n      return dispatch({ type: 'login_errored' })\n    }\n    dispatch({\n      ...answered,\n      result,\n      rememberedUserId: remembered?.value ?? null\n    })\n  }\n\n  function beat(): Promise<void> {\n    const started = epoch\n    const observed = { type: 'session_observed', from: 'this_tab' } as const\n    return answer(started, observed, async () => {\n      const result = await readWebSession(options.session)\n      const shared = result.status === 'ok' || result.code === 'SESSION_REVOKED'\n      if (shared && started === epoch) publish('heartbeat', result)\n      return result\n    })\n  }\n\n  function invalidatePendingSignIns(): void {\n    signOuts += 1\n    liveSignIn = 0\n  }\n\n  function adopt(message: unknown): void {\n    const parsed = zSharedMessage.safeParse(message)\n    if (!parsed.success) return\n    const { from, result } = parsed.data\n    if (from === 'sign_out') invalidatePendingSignIns()\n    const observed = {\n      type: 'session_observed',\n      from: `sibling_${from}`\n    } as const\n    void answer(epoch, observed, async () => result)\n  }\n\n  function wantsBeat(): boolean {\n    return (\n      stopWatching.length > 0 &&\n      state.phase === 'signed_in' &&\n      heartbeat?.visibility.isVisible() === true\n    )\n  }\n\n  function armBeat(): void {\n    cancelBeat = schedule(() => {\n      void beat()\n      armBeat()\n    }, heartbeat?.intervalMs ?? HEARTBEAT_INTERVAL_MS)\n  }\n\n  function lead(): void {\n    if (wantsBeat() && cancelBeat === undefined) armBeat()\n  }\n\n  function syncLeadership(): void {\n    const wanted = wantsBeat()\n    if (wanted && releaseLeadership === undefined) {\n      const port = heartbeat?.crossTab\n      if (port) {\n        releaseLeadership = port.requestLeadership(HEARTBEAT_KEY, lead)\n      } else {\n        releaseLeadership = () => undefined\n        lead()\n      }\n    } else if (!wanted && releaseLeadership !== undefined) {\n      releaseLeadership()\n      releaseLeadership = undefined\n      cancelBeat?.()\n      cancelBeat = undefined\n    }\n  }\n\n  function watch(): void {\n    if (heartbeat === undefined) return\n    const { visibility, crossTab } = heartbeat\n    stopWatching = [\n      visibility.onChange((visible) => {\n        if (visible && state.phase === 'signed_in') void beat()\n        syncLeadership()\n      }),\n      ...(crossTab ? [crossTab.onCredential(HEARTBEAT_KEY, adopt)] : [])\n    ]\n  }\n\n  async function restore(\n    started: number,\n    expectedUserId: string\n  ): Promise<void> {\n    const proof = await login.getProof().then(\n      (value) => ({ value }),\n      () => undefined\n    )\n    if (started !== epoch) return\n    if (proof === undefined) return dispatch({ type: 'proof_errored' })\n    const { value } = proof\n    if (value === null) return dispatch({ type: 'proof_missing' })\n    await answer(started, { type: 'restore_answered' }, () =>\n      createWebSession(options.session, async () => value, { expectedUserId })\n    )\n  }\n\n  function run(effect: WebSessionIdentityEffect): void {\n    switch (effect.type) {\n      case 'read':\n        void answer(epoch, { type: 'read_answered' }, () =>\n          readWebSession(options.session)\n        )\n        return\n      case 'restore':\n        restoring = { epoch, settled: restore(epoch, effect.expectedUserId) }\n        return\n      case 'schedule_retry':\n        cancelRetry = schedule(\n          () => {\n            cancelRetry = undefined\n            dispatch({ type: 'retry_due' })\n          },\n          Math.min(retryBaseMs * 2 ** (effect.failures - 1), retryMaxMs)\n        )\n        return\n      case 'sign_out_locally':\n        login.signOutLocally().catch(reportLocalSignOutFailure)\n        return\n      default:\n        notify(effect)\n    }\n  }\n\n  function notify(effect: WebSessionIdentityEffect): void {\n    switch (effect.type) {\n      case 'report':\n        options.onBootstrap?.({\n          outcome: effect.outcome,\n          origin: options.origin\n        })\n        return\n      case 'account_changed':\n        epoch += 1\n        options.onAccountChanged?.({ ...effect.change, epoch })\n        return\n      case 'report_signed_out_remotely':\n        options.onSignedOutRemotely?.({ origin: options.origin })\n    }\n  }\n\n  function stopHeartbeat(): void {\n    stopWatching.forEach((stop) => stop())\n    stopWatching = []\n    syncLeadership()\n  }\n\n  return {\n    getState: () => state,\n    subscribe: (listener) => {\n      listeners.add(listener)\n      listener(state)\n      return () => {\n        listeners.delete(listener)\n      }\n    },\n    boot: () => {\n      if (state.phase !== 'idle') return\n      watch()\n      dispatch({ type: 'boot' })\n    },\n    signedIn: async (getProof) => {\n      const signOutsAtStart = signOuts\n      const signIn = ++signIns\n      const result = await createWebSession(options.session, getProof)\n      if (result.status !== 'ok') return result\n      if (signOuts !== signOutsAtStart) {\n        // A later sign-in owns the cookie now; deleting would end its session.\n        if (liveSignIn > signIn) return revoked\n        const cleanup = await deleteWebSession(options.session)\n        return cleanup.status === 'ok' ? revoked : cleanup\n      }\n      liveSignIn = signIn\n      dispatch({ type: 'session_created', session: result.session })\n      publish('sign_in', result)\n      return result\n    },\n    signOut: async () => {\n      invalidatePendingSignIns()\n      dispatch({ type: 'sign_out_requested' })\n      const result = await deleteWebSession(options.session)\n      if (result.status === 'ok') publish('sign_out', revoked)\n      return result\n    },\n    refresh: async (expectedUserId) => {\n      if (state.phase !== 'signed_in') return state\n      if ((expectedUserId ?? state.session.user.id) !== state.session.user.id) {\n        return state\n      }\n      await beat()\n      if (restoring.epoch === epoch) await restoring.settled\n      return state\n    },\n    getEpoch: () => epoch,\n    dispose: () => {\n      epoch += 1\n      cancelRetry?.()\n      cancelRetry = undefined\n      stopHeartbeat()\n      state = { phase: 'idle' }\n      listeners.forEach((listener) => listener(state))\n    }\n  }\n}\n\n/** Inert until `boot()`: constructing it sends no request and arms no timer. */\nexport function createWebSessionIdentity(\n  options: WebSessionIdentityOptions\n): WebSessionIdentity {\n  return options.principal.kind === 'api_key'\n    ? createApiKeyIdentity()\n    : createAccountIdentity(options, options.principal.rememberedLogin)\n}\n","import type { AccountCredential, CrossTabRefreshPort } from '../core/session.js'\nimport type { VisibilityPort } from '../core/webSessionIdentity.js'\n\n/**\n * Web Locks + BroadcastChannel implementation of the cross-tab refresh port.\n * The coordination key names both the lock and the channel. Resolves to\n * undefined where either API is missing (older browsers, non-browser and\n * unit-test environments), so hosts fall back to uncoordinated per-tab\n * refresh.\n *\n * Trust boundary, decided rather than assumed: the workspace JWT travels on\n * a same-origin BroadcastChannel whose name any script in the page can\n * derive from the uid and workspace id, and an inbound message is accepted\n * on shape, uid, workspace and a newer expiry, all of which a script in the\n * realm can read and forge. Same-origin script already holds the token and\n * the session client's storage adapter, so this widens what such a script\n * can do to siblings (hand them a token), not what it can reach. Hosts that\n * load third-party script into the realm accept that when they opt in.\n */\nexport function createWebCrossTabRefreshPort<Message = AccountCredential>():\n  | CrossTabRefreshPort<Message>\n  | undefined {\n  // Feature-detect defensively: test DOMs ship these piecemeal (happy-dom\n  // has a BroadcastChannel but a null navigator.locks), and either gap must\n  // resolve to undefined.\n  if (typeof BroadcastChannel === 'undefined') return undefined\n  if (typeof navigator === 'undefined') return undefined\n  const locks = (navigator as Partial<Navigator>).locks\n  if (!locks) return undefined\n  // A present BroadcastChannel can still throw on construction (policy,\n  // sandbox, privacy mode, partial impl); probe once so the port is either\n  // fully usable or absent, never interrupted mid-commit.\n  try {\n    const probe = new BroadcastChannel('@comfyorg/account-core cross-tab probe')\n    probe.close()\n  } catch {\n    return undefined\n  }\n  // One refcounted channel per subscribed key, shared by subscribe and\n  // publish. A channel never delivers a message back to itself, so\n  // publishing on the subscription channel keeps a tab from hearing its own\n  // broadcasts.\n  const channels = new Map<\n    string,\n    { channel: BroadcastChannel; subscribers: number }\n  >()\n  return {\n    requestLeadership(key, onAcquired) {\n      const controller = new AbortController()\n      let disposed = false\n      let releaseHeld: (() => void) | undefined\n      void locks\n        .request(key, { signal: controller.signal }, () => {\n          // A grant can win the race against our own abandon; returning\n          // without holding releases the lock straight to the next tab.\n          if (disposed) return\n          onAcquired()\n          // onAcquired may dispose synchronously, and neither abort() (a\n          // no-op on a granted lock) nor releaseHeld (not wired yet) can\n          // observe that — re-check before committing to the hold.\n          // oxlint-disable-next-line typescript/no-unnecessary-condition -- the narrowing is not call-aware; onAcquired() can flip this\n          if (disposed) return\n          // Hold the lock until released; the browser releases it for us\n          // when the tab dies, which is what promotes the next tab.\n          return new Promise<void>((resolve) => {\n            releaseHeld = resolve\n          })\n        })\n        .catch((error: unknown) => {\n          // Abandoning the request aborts it; anything else means this tab\n          // silently never leads, which deserves a trace.\n          if (error instanceof DOMException && error.name === 'AbortError') {\n            return\n          }\n          console.warn('Cross-tab refresh leadership request failed:', error)\n        })\n      return () => {\n        disposed = true\n        controller.abort()\n        releaseHeld?.()\n      }\n    },\n    publishCredential(key, credential) {\n      const entry = channels.get(key)\n      if (entry !== undefined) {\n        entry.channel.postMessage(credential)\n        return\n      }\n      // No subscriber on this key here: publish on an ephemeral channel so\n      // nothing is left open with no owner to close it.\n      const channel = new BroadcastChannel(key)\n      channel.postMessage(credential)\n      channel.close()\n    },\n    onCredential(key, callback) {\n      let entry = channels.get(key)\n      if (entry === undefined) {\n        entry = { channel: new BroadcastChannel(key), subscribers: 0 }\n        channels.set(key, entry)\n      }\n      entry.subscribers += 1\n      const subscribed = entry\n      const handler = (event: MessageEvent) => {\n        const message: unknown = event.data\n        callback(message)\n      }\n      subscribed.channel.addEventListener('message', handler)\n      let active = true\n      return () => {\n        if (!active) return\n        active = false\n        subscribed.channel.removeEventListener('message', handler)\n        subscribed.subscribers -= 1\n        if (subscribed.subscribers === 0) {\n          subscribed.channel.close()\n          if (channels.get(key) === subscribed) channels.delete(key)\n        }\n      }\n    }\n  }\n}\n\nexport function createWebVisibilityPort(): VisibilityPort | undefined {\n  if (typeof document === 'undefined') return undefined\n  const isVisible = () => document.visibilityState === 'visible'\n  return {\n    isVisible,\n    onChange: (listener) => {\n      const handler = () => listener(isVisible())\n      document.addEventListener('visibilitychange', handler)\n      return () => document.removeEventListener('visibilitychange', handler)\n    }\n  }\n}\n","import { z } from 'zod'\n\nconst STORAGE_KEY = 'Comfy.WebSession.InteractiveSignIn'\nconst MAX_AGE_MS = 2 * 60_000\n\nconst zMarker = z.object({ uid: z.string(), at: z.number() })\n\nexport function markInteractiveSignIn(uid: string): void {\n  try {\n    sessionStorage.setItem(STORAGE_KEY, JSON.stringify({ uid, at: Date.now() }))\n  } catch {\n    return\n  }\n}\n\nexport function clearInteractiveSignIn(): void {\n  try {\n    sessionStorage.removeItem(STORAGE_KEY)\n  } catch {\n    return\n  }\n}\n\n/** True once, and only for a fresh marker written for this Firebase user. */\nexport function takeInteractiveSignIn(uid: string): boolean {\n  let json: unknown\n  try {\n    const raw = sessionStorage.getItem(STORAGE_KEY)\n    clearInteractiveSignIn()\n    if (raw === null) return false\n    json = JSON.parse(raw)\n  } catch {\n    return false\n  }\n  const marker = zMarker.safeParse(json)\n  return (\n    marker.success &&\n    marker.data.uid === uid &&\n    Date.now() - marker.data.at >= 0 &&\n    Date.now() - marker.data.at <= MAX_AGE_MS\n  )\n}\n","import { z } from 'zod'\n\nimport type { WebSession } from '@comfyorg/account-core/webSession'\n\nconst HINT_KEY = 'Comfy.WebSession.SsoHint'\nconst ATTEMPT_KEY = 'Comfy.WebSession.SsoReentryAt'\nconst ATTEMPT_WINDOW_MS = 5 * 60_000\nconst SSO_SIGN_IN_PROVIDERS: ReadonlySet<string> = new Set([\n  'saml.workos',\n  'oidc.workos'\n])\n\nconst zHint = z.object({ email: z.string().min(1) })\nconst zAttemptAt = z.number()\n\n/** A convenience hint, never proof of identity: the session decides that. */\nexport type SsoHint = z.infer<typeof zHint>\n\nfunction parseJson(raw: string | null): unknown {\n  if (raw === null) return undefined\n  try {\n    return JSON.parse(raw)\n  } catch {\n    return undefined\n  }\n}\n\nexport function forgetSsoHint(): void {\n  try {\n    localStorage.removeItem(HINT_KEY)\n  } catch {\n    return\n  }\n}\n\nexport function isSsoSession(user: WebSession['user']): boolean {\n  return SSO_SIGN_IN_PROVIDERS.has(user.signInProvider ?? '')\n}\n\n/** Keyed on the provider the server reports, so only an SSO session leaves a hint. */\nexport function rememberSignedInSession(user: WebSession['user']): void {\n  if (!isSsoSession(user)) {\n    forgetSsoHint()\n    return\n  }\n  const hint: SsoHint = { email: user.email }\n  try {\n    localStorage.setItem(HINT_KEY, JSON.stringify(hint))\n  } catch {\n    return\n  }\n}\n\nexport function readSsoHint(): SsoHint | null {\n  let raw: string | null\n  try {\n    raw = localStorage.getItem(HINT_KEY)\n  } catch {\n    return null\n  }\n  const hint = zHint.safeParse(parseJson(raw))\n  return hint.success ? hint.data : null\n}\n\n/** Unreadable storage counts as recent, so a tab that cannot remember never loops. */\nexport function hasRecentSsoReentry(now = Date.now()): boolean {\n  let raw: string | null\n  try {\n    raw = sessionStorage.getItem(ATTEMPT_KEY)\n  } catch {\n    return true\n  }\n  const at = zAttemptAt.safeParse(parseJson(raw))\n  return at.success && now >= at.data && now - at.data < ATTEMPT_WINDOW_MS\n}\n\n/** False when the attempt could not be recorded; the caller must not redirect. */\nexport function markSsoReentry(now = Date.now()): boolean {\n  try {\n    sessionStorage.setItem(ATTEMPT_KEY, JSON.stringify(now))\n    return true\n  } catch {\n    return false\n  }\n}\n","import { whenever } from '@vueuse/core'\nimport { computed, watch } from 'vue'\n\nimport { desktopHostUser } from '@/platform/auth/desktopHost/desktopHostSession'\nimport { useApiKeyAuthStore } from '@/stores/apiKeyAuthStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useAuthStore } from '@/stores/authStore'\nimport type { AuthUserInfo } from '@/types/authTypes'\n\nexport const useCurrentUser = () => {\n  const authStore = useAuthStore()\n  const commandStore = useCommandStore()\n  const apiKeyStore = useApiKeyAuthStore()\n\n  const sessionUser = computed(() => authStore.sessionUser)\n  const firebaseForSession = computed(() => {\n    const user = authStore.currentUser\n    return !sessionUser.value || user?.uid === sessionUser.value.id\n      ? user\n      : null\n  })\n  // A signed-in identity takes precedence on every auth rail (see\n  // authStore.getUserAuthHeader), so a stored key behind one is not an\n  // API-key session.\n  const isApiKeyLogin = computed(\n    () =>\n      apiKeyStore.isAuthenticated &&\n      authStore.currentUser === null &&\n      !sessionUser.value &&\n      !desktopHostUser.value\n  )\n  const isLoggedIn = computed(\n    () => isApiKeyLogin.value || authStore.isAuthenticated\n  )\n  const isAuthInitialized = computed(() => authStore.isInitialized)\n\n  const resolvedUserInfo = computed<AuthUserInfo | null>(() => {\n    if (isApiKeyLogin.value && apiKeyStore.currentUser) {\n      return { id: apiKeyStore.currentUser.id }\n    }\n\n    if (authStore.userId) return { id: authStore.userId }\n\n    return null\n  })\n\n  const onUserResolved = (callback: (user: AuthUserInfo) => void) =>\n    whenever(resolvedUserInfo, callback, { immediate: true })\n\n  const onTokenRefreshed = (callback: () => void) =>\n    whenever(() => authStore.tokenRefreshTrigger, callback)\n\n  const onUserLogout = (callback: () => void) => {\n    watch(resolvedUserInfo, (user, prevUser) => {\n      if (prevUser && !user) callback()\n    })\n  }\n\n  const userDisplayName = computed(() => {\n    if (desktopHostUser.value) return undefined\n    if (isApiKeyLogin.value) {\n      return apiKeyStore.currentUser?.name\n    }\n    return sessionUser.value?.name ?? firebaseForSession.value?.displayName\n  })\n\n  const userEmail = computed(() => {\n    if (isApiKeyLogin.value) {\n      return apiKeyStore.currentUser?.email\n    }\n    return authStore.userEmail\n  })\n\n  const providerId = computed(\n    () =>\n      sessionUser.value?.signInProvider ??\n      firebaseForSession.value?.providerData[0]?.providerId\n  )\n\n  const providerName = computed(() => {\n    if (isApiKeyLogin.value) {\n      return 'Comfy API Key'\n    }\n    if (providerId.value?.includes('google')) {\n      return 'Google'\n    }\n    if (providerId.value?.includes('github')) {\n      return 'GitHub'\n    }\n    return providerId.value\n  })\n\n  const providerIcon = computed(() => {\n    if (isApiKeyLogin.value) {\n      return 'pi pi-key'\n    }\n    if (providerId.value?.includes('google')) {\n      return 'pi pi-google'\n    }\n    if (providerId.value?.includes('github')) {\n      return 'pi pi-github'\n    }\n    return 'pi pi-user'\n  })\n\n  const isEmailProvider = computed(() => {\n    if (isApiKeyLogin.value || authStore.signedInWithSso) {\n      return false\n    }\n    const firebaseUser = firebaseForSession.value\n    return firebaseUser\n      ? firebaseUser.providerData[0]?.providerId === 'password'\n      : sessionUser.value?.signInProvider === 'password'\n  })\n\n  const needsFirebaseSignIn = computed(\n    () => !!sessionUser.value && !firebaseForSession.value\n  )\n\n  const userPhotoUrl = computed(() => {\n    if (isApiKeyLogin.value) return null\n    return firebaseForSession.value?.photoURL\n  })\n\n  const handleSignOut = async () => {\n    if (isApiKeyLogin.value) {\n      await apiKeyStore.clearStoredApiKey()\n    } else {\n      await commandStore.execute('Comfy.User.SignOut')\n    }\n  }\n\n  const handleSignIn = async () => {\n    await commandStore.execute('Comfy.User.OpenSignInDialog')\n  }\n\n  return {\n    loading: authStore.loading,\n    isAuthInitialized,\n    isLoggedIn,\n    isApiKeyLogin,\n    isEmailProvider,\n    needsFirebaseSignIn,\n    userDisplayName,\n    userEmail,\n    userPhotoUrl,\n    providerName,\n    providerIcon,\n    resolvedUserInfo,\n    handleSignOut,\n    handleSignIn,\n    onUserResolved,\n    onTokenRefreshed,\n    onUserLogout\n  }\n}\n","import type { LocationQuery, LocationQueryRaw } from 'vue-router'\n\nconst STORAGE_PREFIX = 'Comfy.PreservedQuery.'\nconst preservedQueries = new Map<string, Record<string, string>>()\n\nconst readQueryParam = (value: unknown): string | undefined => {\n  if (typeof value === 'string') return value\n  if (!Array.isArray(value)) return undefined\n  return value.find(\n    (entry: unknown): entry is string =>\n      typeof entry === 'string' && entry !== ''\n  )\n}\n\nconst getStorageKey = (namespace: string) => `${STORAGE_PREFIX}${namespace}`\n\nconst isValidQueryRecord = (\n  value: unknown\n): value is Record<string, string> => {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) {\n    return false\n  }\n  return Object.values(value).every((v) => typeof v === 'string')\n}\n\nconst readFromStorage = (namespace: string): Record<string, string> | null => {\n  try {\n    const raw = sessionStorage.getItem(getStorageKey(namespace))\n    if (!raw) return null\n\n    const parsed = JSON.parse(raw)\n    if (!isValidQueryRecord(parsed)) {\n      console.warn('[preservedQuery] invalid storage format')\n      sessionStorage.removeItem(getStorageKey(namespace))\n      return null\n    }\n    return parsed\n  } catch {\n    console.warn('[preservedQuery] storage operation failed')\n    sessionStorage.removeItem(getStorageKey(namespace))\n    return null\n  }\n}\n\nconst writeToStorage = (\n  namespace: string,\n  payload: Record<string, string> | null\n) => {\n  try {\n    if (!payload || Object.keys(payload).length === 0) {\n      sessionStorage.removeItem(getStorageKey(namespace))\n      return\n    }\n    sessionStorage.setItem(getStorageKey(namespace), JSON.stringify(payload))\n  } catch (error) {\n    console.warn('[preservedQuery] failed to write storage', {\n      namespace,\n      error\n    })\n  }\n}\n\nexport const hydratePreservedQuery = (namespace: string) => {\n  if (preservedQueries.has(namespace)) {\n    return\n  }\n  const payload = readFromStorage(namespace)\n  if (payload) {\n    preservedQueries.set(namespace, payload)\n  }\n}\n\n/**\n * By default each capture replaces the namespace stash with the values present\n * in the given query. With `merge`, values are merged into the existing stash\n * and a key supplied with an empty value clears its stashed entry — for\n * namespaces where the stash, not the URL, is the surviving carrier.\n */\nexport const capturePreservedQuery = (\n  namespace: string,\n  query: LocationQuery,\n  keys: string[],\n  { merge = false }: { merge?: boolean } = {}\n) => {\n  if (!merge) {\n    const payload: Record<string, string> = {}\n    keys.forEach((key) => {\n      const value = readQueryParam(query[key])\n      if (value) {\n        payload[key] = value\n      }\n    })\n    if (Object.keys(payload).length === 0) {\n      return\n    }\n    preservedQueries.set(namespace, payload)\n    writeToStorage(namespace, payload)\n    return\n  }\n\n  hydratePreservedQuery(namespace)\n  const payload: Record<string, string> = {\n    ...preservedQueries.get(namespace)\n  }\n  const state = { changed: false }\n\n  keys.forEach((key) => {\n    if (!Object.hasOwn(query, key)) return\n\n    const value = readQueryParam(query[key])\n    if (value) {\n      payload[key] = value\n      state.changed = true\n      return\n    }\n\n    if (key in payload) {\n      delete payload[key]\n      state.changed = true\n    }\n  })\n\n  if (!state.changed) return\n\n  if (Object.keys(payload).length === 0) {\n    preservedQueries.delete(namespace)\n  } else {\n    preservedQueries.set(namespace, payload)\n  }\n  writeToStorage(namespace, payload)\n}\n\nexport function getPreservedQueryParam(\n  namespace: string,\n  key: string\n): string | undefined {\n  hydratePreservedQuery(namespace)\n  return preservedQueries.get(namespace)?.[key]\n}\n\nexport const mergePreservedQueryIntoQuery = (\n  namespace: string,\n  query?: LocationQueryRaw\n): LocationQueryRaw | undefined => {\n  const payload = preservedQueries.get(namespace)\n  if (!payload) return undefined\n\n  const nextQuery: LocationQueryRaw = { ...query }\n  let changed = false\n\n  for (const [key, value] of Object.entries(payload)) {\n    if (typeof nextQuery[key] === 'string') continue\n    nextQuery[key] = value\n    changed = true\n  }\n\n  return changed ? nextQuery : undefined\n}\n\nexport const clearPreservedQuery = (namespace: string) => {\n  if (!preservedQueries.has(namespace)) return\n  preservedQueries.delete(namespace)\n  writeToStorage(namespace, null)\n}\n","export const PRESERVED_QUERY_NAMESPACES = {\n  TEMPLATE: 'template',\n  INVITE: 'invite',\n  SHARE: 'share',\n  SHARE_AUTH: 'share_auth',\n  CREATE_WORKSPACE: 'create_workspace',\n  OAUTH: 'oauth',\n  PRICING: 'pricing',\n  TOPUP: 'topup',\n  SETTINGS: 'settings',\n  ASSETS: 'assets',\n  DESKTOP_LOGIN: 'desktop_login',\n  WORKSPACE: 'workspace'\n} as const\n","import type { MintHandle, SessionResult } from './sessionContracts.js'\n\n// `joined` marks a caller that awaits another owner's in-flight mint rather\n// than starting or cache-serving its own, so it can defer to that owner's\n// commit instead of re-running the publication path.\nexport type MintDispatch = MintHandle & { readonly joined: boolean }\n\nexport interface InFlightMint {\n  readonly promise: Promise<SessionResult>\n  readonly uid: string\n  readonly target: string | undefined\n  readonly forced: boolean\n  readonly mintId: number\n}\n\nexport function canJoin(\n  inFlight: InFlightMint | undefined,\n  uid: string,\n  target: string | undefined,\n  forced: boolean\n): inFlight is InFlightMint {\n  return (\n    inFlight !== undefined &&\n    inFlight.uid === uid &&\n    inFlight.target === target &&\n    (!forced || inFlight.forced)\n  )\n}\n\ninterface MintCoordinator {\n  dispatch: (\n    uid: string,\n    target: string | undefined,\n    forced: boolean,\n    start: () => MintHandle\n  ) => MintDispatch\n  abandon: () => void\n}\n\nexport function createMintCoordinator(): MintCoordinator {\n  let inFlight: InFlightMint | undefined\n\n  return {\n    dispatch(uid, target, forced, start) {\n      if (canJoin(inFlight, uid, target, forced)) {\n        return {\n          mintId: inFlight.mintId,\n          response: inFlight.promise,\n          joined: true\n        }\n      }\n      const { mintId, response } = start()\n      const running = response.finally(() => {\n        if (inFlight?.promise !== running) return\n        inFlight = undefined\n      })\n      inFlight = { promise: running, uid, target, forced, mintId }\n      return { mintId, response: running, joined: false }\n    },\n    abandon() {\n      inFlight = undefined\n    }\n  }\n}\n","/**\n * The contracts the session client shares with the pieces it composes\n * (`exchange`, `refreshScheduler`). Dependency-neutral by design: `session.ts`\n * depends on those pieces, and they depend only on this module, never back on\n * the client — so no top-level binding is ever read before it initializes.\n */\nimport type { zExchangeTokenResponse } from '@comfyorg/ingest-types/zod'\nimport type { z } from 'zod'\n\nexport interface AccountUser {\n  readonly uid: string\n  getIdToken: () => Promise<string>\n}\n\n/** Field types come from the generated POST /api/auth/token contract. */\ntype ExchangeTokenResponse = z.infer<typeof zExchangeTokenResponse>\n\nexport interface AccountCredential {\n  readonly token: string\n  /** ms since epoch */\n  readonly expiresAt: number\n  readonly uid: string\n  readonly workspace: ExchangeTokenResponse['workspace']\n  readonly role: ExchangeTokenResponse['role']\n  readonly permissions: readonly string[]\n}\n\n/**\n * The production store's error taxonomy (`WorkspaceAuthError` codes),\n * emitted as codes only — the host localizes. TOKEN_EXCHANGE_FAILED also\n * covers unparseable bodies, network failures, aborts, and timeouts: a\n * request that produced no usable credential is one failure bucket in\n * production, not three.\n */\nexport type SessionErrorCode =\n  | 'NOT_AUTHENTICATED'\n  | 'INVALID_FIREBASE_TOKEN'\n  | 'ACCESS_DENIED'\n  | 'WORKSPACE_NOT_FOUND'\n  | 'TOKEN_EXCHANGE_FAILED'\n  | 'SSO_REQUIRED'\n\nconst PERMANENT_ERROR_CODES: ReadonlySet<SessionErrorCode> = new Set([\n  'ACCESS_DENIED',\n  'SSO_REQUIRED',\n  'WORKSPACE_NOT_FOUND',\n  'INVALID_FIREBASE_TOKEN',\n  'NOT_AUTHENTICATED'\n])\n\nexport function isPermanentSessionError(code: SessionErrorCode): boolean {\n  return PERMANENT_ERROR_CODES.has(code)\n}\n\nexport type SessionResult =\n  | { readonly status: 'ok'; readonly session: AccountCredential }\n  | {\n      readonly status: 'error'\n      readonly code: SessionErrorCode\n      /** Set only when the failure came from an HTTP response, not aborted/network. */\n      readonly httpStatus?: number\n      /** The organization an `SSO_REQUIRED` refusal names, when ingest names one. */\n      readonly organizationId?: string\n    }\n\nexport type SessionFailure = Extract<SessionResult, { status: 'error' }>\n\n/**\n * The result of one SCHEDULED refresh attempt as a single tagged value: the\n * outcomes that committed a failure carry it and the rest structurally cannot,\n * so a permanent failure without its error — or a success with one — cannot be\n * represented.\n *\n * `failure?: never` is what makes \"structurally cannot\" true rather than\n * aspirational. Without it, excess-property checking still rejects a bad\n * object literal, but a report built in a variable or returned from a helper\n * assigns cleanly.\n */\nexport type ScheduledRefreshReport =\n  | { readonly outcome: 'succeeded'; readonly failure?: never }\n  | { readonly outcome: 'retry_scheduled'; readonly failure?: never }\n  | { readonly outcome: 'retries_exhausted'; readonly failure?: never }\n  | { readonly outcome: 'permanent_failure'; readonly failure: SessionFailure }\n  /** Retries ran out and the credential reached expiry; the client failed closed. */\n  | { readonly outcome: 'expired'; readonly failure: SessionFailure }\n\n/** The outcome discriminants a scheduled refresh can report. */\nexport type SessionRefreshOutcome = ScheduledRefreshReport['outcome']\n\nexport interface MintHandle {\n  readonly mintId: number\n  readonly response: Promise<SessionResult>\n}\n\n/**\n * Cross-tab refresh coordination. One tab per (uid, workspace) key holds the\n * lease and performs the proactive refresh; the others adopt its published\n * credential and mint for themselves only when the leader goes quiet past\n * their jittered fallback. Real hosts wrap Web Locks + BroadcastChannel\n * (`createWebCrossTabRefreshPort` from `@comfyorg/account-core/web`); tests pass\n * fakes.\n */\nexport interface CrossTabRefreshPort<Message = AccountCredential> {\n  /**\n   * Queue for the key's lease. `onAcquired` fires if and when this tab\n   * becomes leader; the returned function abandons the request or releases\n   * held leadership.\n   */\n  requestLeadership: (key: string, onAcquired: () => void) => () => void\n  publishCredential: (key: string, credential: Message) => void\n  /** Messages cross a serialization boundary; the client validates them. */\n  onCredential: (\n    key: string,\n    callback: (message: unknown) => void\n  ) => () => void\n}\n\n/**\n * Opt-in proactive refresh, mirroring the cloud store's scheduled-refresh\n * semantics (its buffer, retry base, and retry cap are the defaults): arm at\n * expiry minus the buffer, retry transient failures with doubling backoff,\n * stop on sign-out, detach, or a permanent failure. Hosts whose consumers\n * read the token synchronously need this; valid-on-read hosts do not.\n */\nexport interface RefreshSchedulerOptions {\n  readonly bufferMs?: number\n  readonly retryBaseMs?: number\n  readonly maxRetries?: number\n  /**\n   * Cross-tab coordination (opt-in): the leader tab refreshes and publishes;\n   * followers adopt the published credential and fall back to their own mint\n   * only after a bounded random hold past the refresh point.\n   */\n  readonly crossTab?: {\n    readonly port: CrossTabRefreshPort\n    /** Upper bound for the follower's random hold. Default 15s. */\n    readonly followerJitterMs?: number\n    /**\n     * Fires when this tab commits a sibling's credential. Adoption is a\n     * rotation the tab did not perform itself, so a host that reacts to\n     * rotations (cookie refresh, extension hooks) needs this signal.\n     */\n    readonly onCredentialAdopted?: (credential: AccountCredential) => void\n  }\n  /**\n   * Called with the result of every SCHEDULED refresh attempt (never a\n   * login or caller-initiated mint), so a host can feed its refresh\n   * telemetry without owning the scheduler. A permanent failure and an\n   * expiry carry the failure the client committed, so the host never has\n   * to read it back out of the snapshot.\n   */\n  readonly onScheduledOutcome?: (report: ScheduledRefreshReport) => void\n}\n\n/** The signed-in principal behind the shared `__Host-comfy_session` cookie. */\nexport interface WebSessionUser {\n  readonly id: string\n  readonly email: string\n  readonly name?: string\n  readonly emailVerified: boolean\n  readonly signInProvider?: string\n  /** Absent when the server does not report it; read absence as true. */\n  readonly hasPersonalWorkspace?: boolean\n}\n\nexport interface WebSession {\n  readonly user: WebSessionUser\n  readonly csrfToken: string\n  /** ms since epoch; the sliding idle expiry */\n  readonly expiresAt: number\n  /** ms since epoch; the hard cap regardless of activity */\n  readonly absoluteExpiresAt: number\n}\n\n/**\n * `SESSION_UNAVAILABLE` is the only transient code: 429, 5xx, network,\n * abort, and unreadable bodies land there so an outage never reads as a\n * sign-out. `SESSION_REQUEST_REFUSED` is a request no fresh session can fix;\n * `SSO_REQUIRED` is the refusal only an SSO sign-in fixes.\n */\nexport type WebSessionErrorCode =\n  | 'NO_SESSION'\n  | 'SESSION_EXPIRED'\n  | 'SESSION_REVOKED'\n  | 'CSRF_STALE'\n  | 'IDENTITY_CHANGED'\n  | 'WORKSPACE_ACCESS_DENIED'\n  | 'SESSION_REQUEST_REFUSED'\n  | 'SSO_REQUIRED'\n  | 'SESSION_UNAVAILABLE'\n\nexport interface WebSessionFailure {\n  readonly status: 'error'\n  readonly code: WebSessionErrorCode\n  readonly retryable: boolean\n  readonly httpStatus?: number\n  /** The server's `ErrorResponse.code`, when the body carried one. */\n  readonly serverCode?: string\n  /** The organization an `SSO_REQUIRED` refusal names. */\n  readonly organizationId?: string\n}\n\nexport type WebSessionResult =\n  | { readonly status: 'ok'; readonly session: WebSession }\n  | WebSessionFailure\n\nexport type WebSessionCommandResult =\n  | { readonly status: 'ok' }\n  | WebSessionFailure\n","/**\n * The proactive-refresh owner: an optional piece the session client hands\n * its lifecycle to when a host asks for scheduled refresh. It owns its own\n * timers, retry count, the expiry fail-close, and (when a cross-tab port is\n * given) the lease, leadership and sibling adoption. It never holds session\n * state: it reads the client's live credential through the host and commits\n * a refreshed, failed, expired or adopted result back through the host, so\n * the client stays the single owner of `credential`/`failure`.\n *\n * Extracted from createSessionClient so the mint/commit core can be reasoned\n * about without the scheduling and cross-tab machinery, and so a client with\n * no `refreshScheduler` option carries none of it.\n */\nimport type {\n  AccountCredential,\n  AccountUser,\n  MintHandle,\n  RefreshSchedulerOptions,\n  SessionFailure\n} from './sessionContracts.js'\nimport { isPermanentSessionError } from './sessionContracts.js'\n\nexport const DEFAULT_BUFFER_MS = 5 * 60 * 1000\n\n/** Guards captured before a scheduled mint, re-checked before its commit. */\ninterface RefreshGuards {\n  readonly epoch: number\n  readonly invalidation: number\n}\n\nexport interface RefreshHost {\n  now: () => number\n  getCurrentUser: () => AccountUser | null\n  getCredential: () => AccountCredential | undefined\n  captureGuards: () => RefreshGuards\n  /** A scheduled mint's result may commit only if nothing superseded it. */\n  guardsHold: (\n    guards: RefreshGuards,\n    user: AccountUser,\n    mintId: number\n  ) => boolean\n  /** A forced mint for the target that produced the live credential. */\n  mint: (user: AccountUser) => MintHandle\n  /** Returns a failure when the refreshed session was rejected (wrong scope). */\n  commitRefreshed: (\n    session: AccountCredential,\n    mintId: number\n  ) => SessionFailure | undefined\n  commitPermanentFailure: (failure: SessionFailure) => void\n  /** Clears iff the live credential is still `expiring`; returns what it committed. */\n  commitExpired: (expiring: AccountCredential) => SessionFailure | undefined\n  /** Parse a cross-tab message into a credential, or undefined if malformed. */\n  parseAdopted: (message: unknown) => AccountCredential | undefined\n  /** Commit a sibling's credential: supersede any in-flight mint, persist, publish. */\n  commitAdopted: (session: AccountCredential) => void\n}\n\nexport interface RefreshScheduler {\n  /** A fresh credential committed: cancel the fail-close, arm the next refresh, tell siblings. */\n  armAfterCommit: (session: AccountCredential, now: number) => void\n  stop: () => void\n}\n\nfunction disposeQuietly(\n  dispose: (() => void) | undefined,\n  label: string\n): void {\n  try {\n    dispose?.()\n  } catch (error) {\n    console.warn(`Cross-tab refresh ${label} teardown failed:`, error)\n  }\n}\n\nexport function createRefreshScheduler(\n  options: RefreshSchedulerOptions,\n  host: RefreshHost\n): RefreshScheduler {\n  const bufferMs = options.bufferMs ?? DEFAULT_BUFFER_MS\n  const retryBaseMs = options.retryBaseMs ?? 5000\n  const maxRetries = options.maxRetries ?? 3\n  const reportOutcome = options.onScheduledOutcome\n  const crossTab = options.crossTab\n  const followerJitterMs = crossTab?.followerJitterMs ?? 15_000\n\n  let scheduledTimer: ReturnType<typeof setTimeout> | undefined\n  /**\n   * The hard fail-close for a credential whose refresh chain died. Its own\n   * timer on purpose: re-arming the refresh (a retry, a promotion) must not\n   * cancel it; only a committed credential or a teardown does.\n   */\n  let expiryTimer: ReturnType<typeof setTimeout> | undefined\n  let scheduledRetryCount = 0\n  /** Without coordination every tab is its own leader. */\n  let isRefreshLeader = crossTab === undefined\n  let coordinationKey: string | undefined\n  /**\n   * Bumped on every coordination teardown. A leadership grant landing on an\n   * abandoned request carries the generation it was issued under — the key\n   * string alone cannot distinguish an abandoned request from its same-key\n   * successor after a sign-out/sign-in round trip.\n   */\n  let coordinationGeneration = 0\n  let armingScheduledRefresh = false\n  let releaseLeadership: (() => void) | undefined\n  let stopCredentialFeed: (() => void) | undefined\n\n  function stopScheduledRefresh(): void {\n    if (scheduledTimer !== undefined) {\n      clearTimeout(scheduledTimer)\n      scheduledTimer = undefined\n    }\n  }\n\n  function clearExpiry(): void {\n    if (expiryTimer !== undefined) {\n      clearTimeout(expiryTimer)\n      expiryTimer = undefined\n    }\n  }\n\n  function teardownCoordination(): void {\n    coordinationGeneration += 1\n    disposeQuietly(releaseLeadership, 'leadership release')\n    releaseLeadership = undefined\n    disposeQuietly(stopCredentialFeed, 'credential feed')\n    stopCredentialFeed = undefined\n    coordinationKey = undefined\n    isRefreshLeader = crossTab === undefined\n  }\n\n  function ensureCoordination(): void {\n    const credential = host.getCredential()\n    if (crossTab === undefined || credential === undefined) return\n    // Keyed by the SERVER-RESOLVED workspace, never the requested target: a\n    // personal {} mint resolves to a concrete workspace the target string\n    // cannot name, and tabs on one workspace must share one lease however\n    // they reached it.\n    const key = `comfy-account-refresh:${credential.uid}:${credential.workspace.id}`\n    if (key === coordinationKey) return\n    teardownCoordination()\n    coordinationKey = key\n    const generationAtRequest = coordinationGeneration\n    // Cross-tab coordination is optional: a port that throws during setup\n    // must never propagate past a committed credential. Tear down whatever\n    // partial wiring landed and lead this tab on its own schedule.\n    try {\n      stopCredentialFeed = crossTab.port.onCredential(\n        key,\n        adoptPublishedCredential\n      )\n      releaseLeadership = crossTab.port.requestLeadership(key, () => {\n        // A grant is honored only for the coordination generation that issued\n        // the request: abandoned requests can still win the grant race in the\n        // lock manager, and after a same-user round trip their key is\n        // byte-identical to the live request's.\n        if (generationAtRequest !== coordinationGeneration) return\n        isRefreshLeader = true\n        // Promotion retakes the schedule unconditionally — the follower timer\n        // may be jittered, mid-retry, or already dead from exhausted retries.\n        // The latch skips the redundant re-arm when the grant fires\n        // synchronously inside armScheduledRefresh itself.\n        const live = host.getCredential()\n        if (live !== undefined && !armingScheduledRefresh) {\n          armScheduledRefresh(live.expiresAt, host.now())\n        }\n      })\n    } catch (error) {\n      console.warn('Cross-tab refresh coordination setup failed:', error)\n      teardownCoordination()\n      isRefreshLeader = true\n    }\n  }\n\n  /**\n   * Every committed mint is published once a coordination key exists —\n   * leadership gates adoption, never publication — so the reactive 401\n   * re-mint and a leaderless follower's fallback reach siblings too: those\n   * are exactly the rotations they must not miss. Adoption itself never\n   * republishes, and the monotonic-expiry guard makes redelivery a no-op,\n   * so the channel cannot loop.\n   */\n  function publishToSiblings(session: AccountCredential): void {\n    if (coordinationKey === undefined) return\n    // Publication is optional: a throwing port must not unwind a mint that\n    // already committed and persisted its credential.\n    try {\n      crossTab?.port.publishCredential(coordinationKey, session)\n    } catch (error) {\n      console.warn('Cross-tab refresh credential publish failed:', error)\n    }\n  }\n\n  function adoptPublishedCredential(message: unknown): void {\n    // Any tab adopts a strictly newer credential, the leader included: a\n    // leader whose own chain died recovers from a sibling's fallback mint,\n    // and the monotonic-expiry check keeps the channel from looping.\n    const next = host.parseAdopted(message)\n    if (next === undefined) return\n    if (host.getCurrentUser()?.uid !== next.uid) return\n    // Scope check: the channel key cannot fully encode the workspace (the\n    // personal target is server-resolved), so a same-user credential minted\n    // for a DIFFERENT workspace must never switch this tab.\n    const credential = host.getCredential()\n    if (credential === undefined) return\n    if (next.workspace.id !== credential.workspace.id) return\n    if (next.expiresAt <= credential.expiresAt) return\n    clearExpiry()\n    host.commitAdopted(next)\n    armScheduledRefresh(next.expiresAt, host.now())\n    crossTab?.onCredentialAdopted?.(next)\n  }\n\n  function armScheduledRefresh(expiresAt: number, now: number): void {\n    stopScheduledRefresh()\n    scheduledRetryCount = 0\n    armingScheduledRefresh = true\n    try {\n      ensureCoordination()\n    } finally {\n      armingScheduledRefresh = false\n    }\n    // A follower holds past the leader's refresh point by bounded random\n    // jitter; when no published credential has arrived by then, the leader\n    // is gone and this tab refreshes for itself. Never tighter than one\n    // retry interval: a token already inside the buffer (a host buffer at\n    // or above the TTL, a skewed clock) would otherwise re-mint in a loop.\n    const jitter = isRefreshLeader ? 0 : Math.random() * followerJitterMs\n    scheduledTimer = setTimeout(\n      () => {\n        scheduledTimer = undefined\n        void runScheduledRefresh()\n      },\n      Math.max(retryBaseMs, expiresAt - bufferMs - now) + jitter\n    )\n  }\n\n  /**\n   * Retries are spent and the credential still has time on it: keep serving\n   * it until its expiry instant, then fail closed and tell the host, as the\n   * cloud store's clear-at-expiry does. A dead scheduler must never leave an\n   * expired token in circulation.\n   */\n  function armClearAtExpiry(expiring: AccountCredential): void {\n    const now = host.now()\n    clearExpiry()\n    expiryTimer = setTimeout(\n      () => {\n        expiryTimer = undefined\n        const committed = host.commitExpired(expiring)\n        if (!committed) return\n        stopScheduledRefresh()\n        reportOutcome?.({ outcome: 'expired', failure: committed })\n      },\n      Math.max(0, expiring.expiresAt - now)\n    )\n  }\n\n  /**\n   * The scheduled re-mint mirrors the cloud store's refresh semantics: a\n   * transient failure keeps the still-valid credential and retries with\n   * doubling backoff; a permanent failure commits the error; exhausted\n   * retries keep the credential until it expires, then fail closed. Every\n   * commit runs publish() before reporting its outcome — host outcome\n   * handlers read state the publish just wrote.\n   */\n  async function runScheduledRefresh(): Promise<void> {\n    const user = host.getCurrentUser()\n    if (!user) return\n    const guards = host.captureGuards()\n    // Refresh with the target that produced the live credential, so a\n    // scheduled refresh reproduces the same session AND coalesces with any\n    // concurrent reactive re-mint for it.\n    const { mintId, response } = host.mint(user)\n    let result\n    try {\n      result = await response\n    } catch {\n      result = { status: 'error', code: 'TOKEN_EXCHANGE_FAILED' } as const\n    }\n    if (!host.guardsHold(guards, user, mintId)) return\n    if (result.status === 'ok') {\n      const rejected = host.commitRefreshed(result.session, mintId)\n      if (rejected) {\n        reportOutcome?.({ outcome: 'permanent_failure', failure: rejected })\n        return\n      }\n      clearExpiry()\n      armScheduledRefresh(result.session.expiresAt, host.now())\n      publishToSiblings(result.session)\n      reportOutcome?.({ outcome: 'succeeded' })\n      return\n    }\n    if (isPermanentSessionError(result.code)) {\n      host.commitPermanentFailure(result)\n      reportOutcome?.({ outcome: 'permanent_failure', failure: result })\n      return\n    }\n    if (scheduledRetryCount >= maxRetries) {\n      const live = host.getCredential()\n      if (live !== undefined) armClearAtExpiry(live)\n      // A leader with a dead chain must not sit on the lease: release it so\n      // a sibling can lead, and queue again as a follower so this tab can\n      // adopt what that sibling mints or be promoted back if nobody does.\n      teardownCoordination()\n      ensureCoordination()\n      reportOutcome?.({ outcome: 'retries_exhausted' })\n      return\n    }\n    const delay = retryBaseMs * 2 ** scheduledRetryCount\n    scheduledRetryCount += 1\n    stopScheduledRefresh()\n    scheduledTimer = setTimeout(() => {\n      scheduledTimer = undefined\n      void runScheduledRefresh()\n    }, delay)\n    reportOutcome?.({ outcome: 'retry_scheduled' })\n  }\n\n  return {\n    armAfterCommit(session, now) {\n      clearExpiry()\n      armScheduledRefresh(session.expiresAt, now)\n      publishToSiblings(session)\n    },\n    stop() {\n      stopScheduledRefresh()\n      clearExpiry()\n      teardownCoordination()\n    }\n  }\n}\n","/**\n * The session's authoritative state and its only commit boundary. Effects\n * come back in the order the client must run them: persist before arming\n * the scheduler, publish last, so a host reacting to a snapshot never reads\n * state a later step would still change.\n */\nimport type {\n  AccountCredential,\n  AccountUser,\n  SessionFailure\n} from './sessionContracts.js'\nimport { isPermanentSessionError } from './sessionContracts.js'\n\nexport interface SessionState<TUser extends AccountUser = AccountUser> {\n  readonly user: TUser | null\n  readonly identitySettled: boolean\n  readonly credential: AccountCredential | undefined\n  readonly credentialTarget: string | undefined\n  readonly failure: SessionFailure | undefined\n  /**\n   * The result the winning mint published, so a caller joining that same mint\n   * returns it instead of running the commit/publication path a second time.\n   */\n  readonly committedMint:\n    | { readonly mintId: number; readonly session: AccountCredential }\n    | undefined\n  /**\n   * Bumped on every identity event so a mint can tell \"the listener has not\n   * settled yet\" (the legitimate popup path) from \"an identity event\n   * happened while I was in flight\" (must invalidate).\n   */\n  readonly identityEpoch: number\n  readonly invalidationEpoch: number\n  /**\n   * Monotonic id taken by every started mint; a commit is allowed only for\n   * the newest one. Target-agnostic on purpose — a slower mint for the old\n   * workspace resolving after a switch must never revert it. Ports the\n   * cloud store's unifiedRefreshRequestId guard.\n   */\n  readonly mintSequence: number\n}\n\nexport function initialSessionState<\n  TUser extends AccountUser = AccountUser\n>(): SessionState<TUser> {\n  return {\n    user: null,\n    identitySettled: false,\n    credential: undefined,\n    credentialTarget: undefined,\n    failure: undefined,\n    committedMint: undefined,\n    identityEpoch: 0,\n    invalidationEpoch: 0,\n    mintSequence: 0\n  }\n}\n\nexport type SessionEvent<TUser extends AccountUser = AccountUser> =\n  | { readonly type: 'identity-changed'; readonly user: TUser | null }\n  | { readonly type: 'identity-detached' }\n  | { readonly type: 'invalidated' }\n  | { readonly type: 'mint-started' }\n  | {\n      readonly type: 'mint-committed'\n      readonly origin: 'caller'\n      readonly session: AccountCredential\n      readonly target: string | undefined\n      readonly mintId: number\n    }\n  | {\n      readonly type: 'mint-committed'\n      readonly origin: 'scheduler'\n      readonly session: AccountCredential\n      readonly mintId: number\n    }\n  | {\n      readonly type: 'mint-rejected'\n      readonly origin: 'caller'\n      readonly failure: SessionFailure\n      readonly preserveCredentialOnTransientFailure: boolean\n    }\n  | {\n      readonly type: 'mint-rejected'\n      readonly origin: 'scheduler'\n      readonly failure: SessionFailure\n    }\n  | { readonly type: 'credential-adopted'; readonly session: AccountCredential }\n  | {\n      readonly type: 'credential-expired'\n      readonly expiring: AccountCredential\n    }\n\nexport type SessionEffect =\n  | {\n      readonly type: 'persist'\n      readonly session: AccountCredential\n      readonly target: string | undefined\n    }\n  | { readonly type: 'armScheduler'; readonly session: AccountCredential }\n  | { readonly type: 'clearStorage' }\n  | { readonly type: 'stopScheduler' }\n  | { readonly type: 'abandonInFlight' }\n  | { readonly type: 'publish' }\n\nexport interface SessionTransition<TUser extends AccountUser = AccountUser> {\n  readonly state: SessionState<TUser>\n  readonly effects: readonly SessionEffect[]\n}\n\nconst clearStorage: SessionEffect = { type: 'clearStorage' }\nconst stopScheduler: SessionEffect = { type: 'stopScheduler' }\nconst abandonInFlight: SessionEffect = { type: 'abandonInFlight' }\nconst publish: SessionEffect = { type: 'publish' }\n\ntype EventOf<\n  TUser extends AccountUser,\n  TType extends SessionEvent<TUser>['type']\n> = Extract<SessionEvent<TUser>, { type: TType }>\n\nfunction dropSession<TUser extends AccountUser>(\n  state: SessionState<TUser>\n): SessionState<TUser> {\n  return {\n    ...state,\n    credential: undefined,\n    credentialTarget: undefined,\n    failure: undefined\n  }\n}\n\nfunction applyIdentityChanged<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  event: EventOf<TUser, 'identity-changed'>\n): SessionTransition<TUser> {\n  return {\n    state: {\n      ...dropSession(state),\n      user: event.user,\n      identitySettled: true,\n      identityEpoch: state.identityEpoch + 1\n    },\n    // A sign-out or a different user makes the running mint unjoinable: it\n    // was started with the previous identity's token, and a caller arriving\n    // after the event must mint for itself. A same-uid re-auth must not\n    // adopt it either.\n    effects:\n      event.user === null\n        ? [stopScheduler, abandonInFlight, clearStorage, publish]\n        : [stopScheduler, abandonInFlight, publish]\n  }\n}\n\nfunction applyIdentityDetached<TUser extends AccountUser>(\n  state: SessionState<TUser>\n): SessionTransition<TUser> {\n  return {\n    state: {\n      ...dropSession(state),\n      user: null,\n      identitySettled: false,\n      identityEpoch: state.identityEpoch + 1\n    },\n    effects: [stopScheduler, publish]\n  }\n}\n\nfunction applyInvalidated<TUser extends AccountUser>(\n  state: SessionState<TUser>\n): SessionTransition<TUser> {\n  // A mint still running belongs to the scope being discarded; a caller\n  // arriving after this must start its own rather than join it.\n  return {\n    state: {\n      ...dropSession(state),\n      invalidationEpoch: state.invalidationEpoch + 1\n    },\n    effects: [stopScheduler, abandonInFlight, clearStorage, publish]\n  }\n}\n\nfunction applyMintStarted<TUser extends AccountUser>(\n  state: SessionState<TUser>\n): SessionTransition<TUser> {\n  return {\n    state: { ...state, mintSequence: state.mintSequence + 1 },\n    effects: []\n  }\n}\n\nfunction applyMintCommitted<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  event: EventOf<TUser, 'mint-committed'>\n): SessionTransition<TUser> {\n  const target =\n    event.origin === 'caller' ? event.target : state.credentialTarget\n  const persist: SessionEffect = {\n    type: 'persist',\n    session: event.session,\n    target\n  }\n  return {\n    state: {\n      ...state,\n      credential: event.session,\n      credentialTarget: target,\n      committedMint: { mintId: event.mintId, session: event.session },\n      failure: undefined\n    },\n    effects:\n      event.origin === 'caller'\n        ? [persist, { type: 'armScheduler', session: event.session }, publish]\n        : [persist, publish]\n  }\n}\n\nfunction applySchedulerRejection<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  failure: SessionFailure\n): SessionTransition<TUser> {\n  return {\n    state: { ...dropSession(state), failure },\n    effects: [clearStorage, publish]\n  }\n}\n\nfunction applyCallerRejection<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  event: EventOf<TUser, 'mint-rejected'> & { readonly origin: 'caller' }\n): SessionTransition<TUser> {\n  const permanent = isPermanentSessionError(event.failure.code)\n  if (\n    !permanent &&\n    event.preserveCredentialOnTransientFailure &&\n    state.credential !== undefined\n  ) {\n    return { state, effects: [] }\n  }\n  if (!permanent) {\n    return {\n      state: { ...state, credential: undefined, failure: event.failure },\n      effects: [publish]\n    }\n  }\n  // A caller-initiated permanent failure must retire the armed scheduler\n  // and target too, or its old timer could resurrect the dead session.\n  return {\n    state: { ...dropSession(state), failure: event.failure },\n    effects: [stopScheduler, clearStorage, publish]\n  }\n}\n\nfunction applyMintRejected<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  event: EventOf<TUser, 'mint-rejected'>\n): SessionTransition<TUser> {\n  return event.origin === 'scheduler'\n    ? applySchedulerRejection(state, event.failure)\n    : applyCallerRejection(state, event)\n}\n\nfunction applyCredentialAdopted<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  event: EventOf<TUser, 'credential-adopted'>\n): SessionTransition<TUser> {\n  // Adoption is a commit: it supersedes any in-flight mint of this\n  // tab's own, exactly like a newer mint would.\n  return {\n    state: {\n      ...state,\n      mintSequence: state.mintSequence + 1,\n      credential: event.session,\n      failure: undefined\n    },\n    effects: [\n      {\n        type: 'persist',\n        session: event.session,\n        target: state.credentialTarget\n      },\n      publish\n    ]\n  }\n}\n\nfunction applyCredentialExpired<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  event: EventOf<TUser, 'credential-expired'>\n): SessionTransition<TUser> {\n  if (state.credential !== event.expiring) return { state, effects: [] }\n  return {\n    state: {\n      ...dropSession(state),\n      failure: { status: 'error', code: 'TOKEN_EXCHANGE_FAILED' }\n    },\n    effects: [clearStorage, publish]\n  }\n}\n\nexport function transition<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  event: SessionEvent<TUser>\n): SessionTransition<TUser> {\n  switch (event.type) {\n    case 'identity-changed':\n      return applyIdentityChanged(state, event)\n    case 'identity-detached':\n      return applyIdentityDetached(state)\n    case 'invalidated':\n      return applyInvalidated(state)\n    case 'mint-started':\n      return applyMintStarted(state)\n    case 'mint-committed':\n      return applyMintCommitted(state, event)\n    case 'mint-rejected':\n      return applyMintRejected(state, event)\n    case 'credential-adopted':\n      return applyCredentialAdopted(state, event)\n    case 'credential-expired':\n      return applyCredentialExpired(state, event)\n  }\n}\n\nexport interface MintAttempt {\n  readonly mintId: number\n  /** Awaited another owner's in-flight mint instead of starting its own. */\n  readonly joined: boolean\n  readonly explicitUser: boolean\n  readonly userUid: string\n  readonly requestedTarget: string | undefined\n  readonly startEpoch: number\n  readonly startInvalidation: number\n  readonly startedSignedOut: boolean\n}\n\nexport type MintVerdict =\n  | { readonly verdict: 'commit' }\n  | { readonly verdict: 'reuse'; readonly session: AccountCredential }\n  | { readonly verdict: 'superseded' }\n\nconst SUPERSEDED: MintVerdict = { verdict: 'superseded' }\n\nfunction supersededByInvalidation<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  attempt: MintAttempt\n): boolean {\n  return state.invalidationEpoch !== attempt.startInvalidation\n}\n\n// The newest mint won, but when it committed a credential for this\n// caller's exact target, that credential answers the request — a lost\n// race is not a failure. A different target (or none) stays undefined.\nfunction lostRace<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  attempt: MintAttempt\n): MintVerdict | undefined {\n  if (attempt.mintId === state.mintSequence) return undefined\n  const answered =\n    state.credential !== undefined &&\n    state.credential.uid === attempt.userUid &&\n    state.user?.uid === attempt.userUid &&\n    attempt.requestedTarget === state.credentialTarget\n  return answered ? { verdict: 'reuse', session: state.credential } : SUPERSEDED\n}\n\nfunction crossedIdentityEvent<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  attempt: MintAttempt\n): boolean {\n  return state.identityEpoch !== attempt.startEpoch\n}\n\n// The one mint allowed to cross an identity event: an explicit-user\n// mint started while signed out, for the user the port then\n// delivered (the popup path) as the single event since. Everything else\n// was minted for an identity that is gone, even when the uid matches again.\nfunction popupSettled<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  attempt: MintAttempt\n): boolean {\n  return (\n    attempt.explicitUser &&\n    attempt.startedSignedOut &&\n    state.identityEpoch === attempt.startEpoch + 1 &&\n    state.user?.uid === attempt.userUid\n  )\n}\n\n// The explicit-user bypass is the popup path, valid only before the\n// identity port has ever fired; a settled null identity blocks it.\nfunction userMismatchBlocksCommit<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  attempt: MintAttempt\n): boolean {\n  return (\n    state.user?.uid !== attempt.userUid &&\n    (!attempt.explicitUser || state.user !== null || state.identitySettled)\n  )\n}\n\nfunction joinerReuse<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  attempt: MintAttempt\n): MintVerdict | undefined {\n  return attempt.joined &&\n    state.committedMint !== undefined &&\n    state.committedMint.mintId === attempt.mintId &&\n    state.credential === state.committedMint.session\n    ? { verdict: 'reuse', session: state.committedMint.session }\n    : undefined\n}\n\nexport function arbitrateMint<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  attempt: MintAttempt\n): MintVerdict {\n  if (supersededByInvalidation(state, attempt)) return SUPERSEDED\n  const raced = lostRace(state, attempt)\n  if (raced) return raced\n  const stale = crossedIdentityEvent(state, attempt)\n    ? !popupSettled(state, attempt)\n    : userMismatchBlocksCommit(state, attempt)\n  if (stale) return SUPERSEDED\n  return joinerReuse(state, attempt) ?? { verdict: 'commit' }\n}\n\nexport function scheduledMintHolds<TUser extends AccountUser>(\n  state: SessionState<TUser>,\n  guards: { readonly epoch: number; readonly invalidation: number },\n  userUid: string,\n  mintId: number\n): boolean {\n  return (\n    mintId === state.mintSequence &&\n    state.user?.uid === userUid &&\n    state.identityEpoch === guards.epoch &&\n    state.invalidationEpoch === guards.invalidation\n  )\n}\n","/**\n * The workspace session: a short-lived JWT minted from the signed-in\n * identity, which is what actually authorizes runs and balance reads.\n *\n * The exchange contract, response schema, and error taxonomy are extracted\n * from the cloud app's production implementation of this same POST\n * /auth/token call (`requestToken` in\n * src/platform/workspace/stores/workspaceAuthStore.ts) — keep the two in\n * step. Only the freshness strategy differs: valid-on-read (callers await\n * `ensureFresh` at the moment they need a token; it never resolves with\n * less than `freshMarginMs` of validity) rather than a proactive refresh\n * timer, because background tabs throttle timers and this package's callers\n * can await. A host that needs proactive refresh wraps this client with its\n * own scheduler.\n *\n * The credential cache sits behind the host's storage adapter keyed to the\n * signed-in uid, so a token survives a reload but can never be served to a\n * different signed-in user.\n */\nimport type { CredentialStorage } from './credentialCache.js'\nimport {\n  DEFAULT_FRESH_MARGIN_MS,\n  createCredentialCache,\n  decodeAdopted,\n  isCredentialFresh,\n  selectFreshCredential\n} from './credentialCache.js'\nimport type { AccountIdentity } from './identity.js'\nimport { abortable, exchangeToken } from './exchange.js'\nimport type { MintDispatch } from './mintCoordinator.js'\nimport { createMintCoordinator } from './mintCoordinator.js'\nimport type { RefreshHost } from './refreshScheduler.js'\nimport { createRefreshScheduler } from './refreshScheduler.js'\nimport type {\n  AccountCredential,\n  AccountUser,\n  RefreshSchedulerOptions,\n  SessionErrorCode,\n  SessionFailure,\n  SessionResult\n} from './sessionContracts.js'\nimport type {\n  SessionEffect,\n  SessionEvent,\n  SessionTransition\n} from './sessionState.js'\nimport {\n  arbitrateMint,\n  initialSessionState,\n  scheduledMintHolds,\n  transition\n} from './sessionState.js'\n\nexport type { AccountIdentity } from './identity.js'\nexport type {\n  AccountCredential,\n  AccountUser,\n  CrossTabRefreshPort,\n  MintHandle,\n  RefreshSchedulerOptions,\n  ScheduledRefreshReport,\n  SessionErrorCode,\n  SessionFailure,\n  SessionRefreshOutcome,\n  SessionResult\n} from './sessionContracts.js'\nexport { isPermanentSessionError } from './sessionContracts.js'\nexport type { CredentialStorage } from './credentialCache.js'\nexport { isCredentialFresh } from './credentialCache.js'\n\n/**\n * The session error codes, keys only. Hosts own the copy (the cloud app's\n * workspaceAuth.errors.*); the package ships the vocabulary so a host can\n * narrow an arbitrary error code to one it has a line for. Exhaustive by\n * type: a new SessionErrorCode is a compile error until it is listed here.\n */\nexport const SESSION_ERROR_CODES: Readonly<Record<SessionErrorCode, true>> = {\n  NOT_AUTHENTICATED: true,\n  INVALID_FIREBASE_TOKEN: true,\n  ACCESS_DENIED: true,\n  WORKSPACE_NOT_FOUND: true,\n  TOKEN_EXCHANGE_FAILED: true,\n  SSO_REQUIRED: true\n}\n\nexport { SESSION_TELEMETRY_EVENT } from '../telemetry.js'\n\nexport interface SessionRequestOptions {\n  readonly fetchImpl?: typeof fetch\n  readonly now?: () => number\n  readonly signal?: AbortSignal\n  readonly timeoutMs?: number\n  /** Mint for this workspace instead of the server-resolved personal one. */\n  readonly workspaceId?: string\n  /**\n   * On a transient remint failure, keep the currently published credential\n   * instead of committing the error — for hosts whose still-valid token\n   * must survive a failed proactive or reactive refresh. Permanent\n   * failures always commit.\n   */\n  readonly preserveCredentialOnTransientFailure?: boolean\n}\n\nexport interface SessionClientOptions extends SessionRequestOptions {\n  readonly exchangeUrl: string\n  readonly storage: CredentialStorage\n  readonly freshMarginMs?: number\n  readonly refreshScheduler?: RefreshSchedulerOptions\n  /**\n   * When false, an identity event sets the user and publishes without\n   * starting a warm-up mint — for hosts that drive every mint explicitly.\n   */\n  readonly autoMint?: boolean\n}\n\n/**\n * `pending` is the initial phase, before the identity has delivered even\n * once, so a host can tell \"Firebase