heduledOutcome: handleScheduledRefreshOutcome,\n        ...(crossTabRefreshPort && {\n          crossTab: {\n            port: crossTabRefreshPort,\n            // A sibling's rotation is still a rotation for this tab: the\n            // session cookie and the onAuthTokenRefreshed hook must see it.\n            onCredentialAdopted: () => useAuthStore().notifyTokenRefreshed()\n          }\n        })\n      }\n    },\n    // Observer order against authStore is not load-bearing: unifiedUser() waits for the port's user and fails closed on the ceiling.\n    firebaseIdentity\n  )\n\n  const stopUnifiedSnapshot = unifiedSessionClient.subscribe((snapshot) => {\n    if (snapshot.phase === 'authenticated') {\n      const target = currentUnifiedTarget() ?? personalWorkspaceTarget()\n      unifiedTarget = target\n      unifiedToken.value = snapshot.session.token\n      unifiedTokenOwnerUid.value = snapshot.session.uid\n      unifiedPermanentFailureSurfaced = false\n      // Any successful mint re-arms the scheduler with a fresh retry budget;\n      // this telemetry mirror must follow it or retry_count inflates.\n      unifiedScheduledRetryCount = 0\n      // A unified mint retires the legacy token so a flag rollback cannot serve\n      // a stale legacy session under the workspace unified just minted.\n      retireLegacyToken()\n      currentWorkspace.value = {\n        ...snapshot.session.workspace,\n        role: snapshot.session.role\n      }\n      persistWorkspaceIdentity(currentWorkspace.value)\n      issuedUnifiedTokenContexts.set(snapshot.session.token, {\n        ownerUid: snapshot.session.uid,\n        targetKey: unifiedTargetKey(target),\n        expiresAt: snapshot.session.expiresAt\n      })\n      pruneExpiredUnifiedTokenContexts(Date.now())\n      return\n    }\n    unifiedToken.value = null\n    unifiedTokenOwnerUid.value = null\n  })\n\n  // Identity is bound for the store's lifetime; the flag gates minting, and a\n  // rollback invalidates the credential, so scheduler and cross-tab lease stop.\n  const stopUnifiedFlagWatch = watch(\n    () => flags.unifiedCloudAuthEnabled,\n    (enabled) => {\n      if (enabled) {\n        void mintAtLogin()\n        return\n      }\n      clearUnifiedContext()\n    }\n  )\n\n  /**\n   * The user the port has delivered, once it is the app's current user\n   * (both are projections of one Auth instance; the port's user is what\n   * mints). Resolves null when nobody is signed in, when a different\n   * identity arrives first, or when the port stays silent past the\n   * ceiling, so a caller can fail closed instead of hanging.\n   */\n  function unifiedUser(): Promise<User | null> {\n    const expectedUid = useAuthStore().currentUser?.uid ?? null\n    const matches = (user: User | null) => (user?.uid ?? null) === expectedUid\n    const current = unifiedSessionClient.getSnapshot().user\n    if (matches(current)) return Promise.resolve(current)\n    return new Promise((resolve) => {\n      // Held in an object: subscribe() replays synchronously, and a settle\n      // from that replay must never touch a binding declared after it.\n      const subscription = { stop: () => {} }\n      const settle = (user: User | null) => {\n        clearTimeout(ceiling)\n        subscription.stop()\n        resolve(user)\n      }\n      const ceiling = setTimeout(() => {\n        console.warn('Unified identity did not settle before the ceiling')\n        settle(null)\n      }, UNIFIED_IDENTITY_SETTLE_TIMEOUT_MS)\n      subscription.stop = unifiedSessionClient.subscribe(({ user }) => {\n        if (matches(user)) settle(user)\n        else if ((user?.uid ?? null) !== (current?.uid ?? null)) settle(null)\n      })\n    })\n  }\n\n  function pruneExpiredUnifiedTokenContexts(now: number): void {\n    for (const [token, context] of issuedUnifiedTokenContexts) {\n      if (context.expiresAt + ISSUED_TOKEN_CONTEXT_GRACE_MS < now) {\n        issuedUnifiedTokenContexts.delete(token)\n      }\n    }\n  }\n\n  function clearUnifiedContext(): void {\n    unifiedScheduledRetryCount = 0\n    unifiedPermanentFailureSurfaced = false\n    issuedUnifiedTokenContexts.clear()\n    unifiedTarget = null\n    // Fails closed through the client: drops its credential, cancels\n    // scheduled work, and blocks in-flight mints from committing.\n    unifiedSessionClient.invalidate()\n  }\n\n  async function switchUnifiedWorkspace(workspaceId: string): Promise<void> {\n    clearWorkspaceContext()\n    const { useSessionCookie } =\n      await import('@/platform/auth/session/useSessionCookie')\n    await useSessionCookie().ensureSessionCookie()\n    const authUser = await unifiedUser()\n    // A rollback during the awaits above must abort the unified switch rather\n    // than commit a token for a flag that is now off.\n    if (!unifiedRailEnabled()) return\n    if (!authUser) {\n      throw new WorkspaceAuthError('Workspace identity changed during switch')\n    }\n    unifiedTarget = { workspace_id: workspaceId }\n    const result = await unifiedSessionClient.remint(authUser, { workspaceId })\n    if (result?.status === 'ok') return\n    // A workspace we could not enter must not become the next login's\n    // target, or an unreachable workspace locks the user out of the personal\n    // session that would have worked.\n    unifiedTarget = null\n    if (result === undefined) {\n      throw new WorkspaceAuthError('Workspace identity changed during switch')\n    }\n    throw new WorkspaceAuthError(\n      t(sessionErrorMessageKey(result.code)),\n      result.code\n    )\n  }\n\n  function trackUnifiedRefresh(outcome: UnifiedAuthRefreshOutcome): void {\n    useTelemetry()?.trackUnifiedAuthRefresh({\n      outcome,\n      ...(outcome !== 'succeeded' && {\n        retry_count: unifiedScheduledRetryCount\n      })\n    })\n  }\n\n  const mintAtLogin = async (): Promise<boolean> => {\n    if (!flags.unifiedCloudAuthEnabled) {\n      return false\n    }\n    if (getUnifiedToken()) {\n      return true\n    }\n    // A unified credential on a session tab would join a sibling's cross-tab\n    // lease and overwrite currentWorkspace when it adopts their token.\n    if (await signedInOnWebSession()) {\n      return false\n    }\n    const authUser = await unifiedUser()\n    // Re-check after the wait: a rollback or a session sign-in while a mint\n    // is parked on unifiedUser() must not let the resumed mint commit a token.\n    if (\n      !unifiedRailEnabled() ||\n      !authUser ||\n      (webSessionRequests() !== undefined && (await signedInOnWebSession()))\n    ) {\n      return false\n    }\n    const target = currentUnifiedTarget() ?? personalWorkspaceTarget()\n    unifiedTarget = target\n    const result = await unifiedSessionClient.ensureFresh(authUser, {\n      workspaceId: unifiedWorkspaceIdFor(target)\n    })\n    if (result?.status === 'ok') {\n      return true\n    }\n    if (result?.status === 'error') {\n      if (isPermanentSessionError(result.code)) {\n        surfaceUnifiedPermanentFailure(result.code)\n      } else {\n        console.warn('Unified login mint failed:', result.code)\n      }\n      return false\n    }\n    // An undefined result means another identity event superseded this\n    // call; the login succeeded iff a token was committed for it.\n    return getUnifiedToken() !== undefined\n  }\n\n  const remintUnifiedOnce = async (\n    expectedToken: string\n  ): Promise<string | null> => {\n    if (!flags.unifiedCloudAuthEnabled) {\n      return null\n    }\n    const target = currentUnifiedTarget()\n    const ownerUid = currentUserUid()\n    const currentToken = getUnifiedToken()\n    const expectedContext = issuedUnifiedTokenContexts.get(expectedToken)\n    if (\n      !target ||\n      !ownerUid ||\n      !currentToken ||\n      expectedContext?.ownerUid !== ownerUid ||\n      expectedContext.targetKey !== unifiedTargetKey(target)\n    ) {\n      return null\n    }\n    if (expectedToken !== currentToken) return currentToken\n    const authUser = await unifiedUser()\n    if (!unifiedRailEnabled() || !authUser) return null\n    const result = await unifiedSessionClient.remint(authUser, {\n      workspaceId: unifiedWorkspaceIdFor(target),\n      preserveCredentialOnTransientFailure: true\n    })\n    if (result?.status === 'ok') {\n      useAuthStore().notifyTokenRefreshed()\n      return getUnifiedToken() ?? null\n    }\n    if (result?.status === 'error' && isPermanentSessionError(result.code)) {\n      surfaceUnifiedPermanentFailure(result.code)\n      endWorkspaceSession(\n        unifiedSelectionInvalid(result.code)\n          ? (currentWorkspace.value?.id ?? undefined)\n          : undefined,\n        result.code\n      )\n    } else if (result?.status === 'error') {\n      console.warn('Unified reactive re-mint failed:', result.code)\n    }\n    return null\n  }\n\n  function getUnifiedToken(): string | undefined {\n    return unifiedToken.value !== null &&\n      unifiedTokenOwnerUid.value !== null &&\n      isCurrentUser(unifiedTokenOwnerUid.value)\n      ? unifiedToken.value\n      : undefined\n  }\n\n  function clearWorkspaceContext(): void {\n    deniedWorkspaceId.value = null\n    clearLegacyContext()\n    error.value = null\n    clearSessionStorage()\n    clearUnifiedContext()\n  }\n\n  function endWorkspaceSession(\n    revokedWorkspaceId?: string,\n    refusalCode?: string\n  ): boolean {\n    const hadContext = currentWorkspace.value !== null\n    const cancelWorkflowTransition =\n      isCloud && hadContext ? prepareWorkflowWorkspaceTransition() : undefined\n    // A reload would take down the SSO-required screen this refusal opens.\n    if (\n      refusalCode === 'SSO_REQUIRED' &&\n      presentSsoRequired('session_refused', {\n        email: useAuthStore().userEmail ?? undefined\n      })\n    ) {\n      clearWorkspaceContext()\n      cancelWorkflowTransition?.()\n      return false\n    }\n    const revokedWorkspaceHandled = revokedWorkspaceId\n      ? useTeamWorkspaceStore().forgetRevokedActiveWorkspace(revokedWorkspaceId)\n      : false\n    clearWorkspaceContext()\n    const shouldReload = revokedWorkspaceId\n      ? !revokedWorkspaceHandled\n      : hadContext\n    if (isCloud && shouldReload) {\n      window.location.reload()\n      return false\n    }\n    cancelWorkflowTransition?.()\n    return !isCloud && revokedWorkspaceHandled\n  }\n\n  return {\n    // State\n    currentWorkspace,\n    deniedWorkspaceId,\n    workspaceToken,\n    unifiedToken,\n    isLoading,\n    error,\n\n    // Getters\n    isAuthenticated,\n\n    // Actions\n    init,\n    destroy,\n    initializeFromSession,\n    switchWorkspace,\n    refreshToken,\n    mintAtLogin,\n    remintUnifiedOnce,\n    getWorkspaceAuthHeader,\n    ensureWorkspaceAuthHeader,\n    ensureWorkspaceToken,\n    getWorkspaceToken,\n    getUnifiedToken,\n    getUnifiedSessionClient,\n    getUnifiedMintWorkspaceId,\n    clearWorkspaceContext,\n    clearUnifiedContext,\n    dropDeniedWorkspace\n  }\n})\n","import type { AxiosInstance, AxiosResponse, RawAxiosHeaders } from 'axios'\nimport axios, { AxiosHeaders } from 'axios'\n\nconst CAPABILITY_REVISION_HEADER = 'X-Capability-Revision'\n// The capability read echoes the header on its own response, so only a\n// mutation counts as an invalidation signal: publishing a read's own revision\n// would mark that read stale and refetch it forever.\nconst MUTATION_METHODS = new Set(['post', 'put', 'patch', 'delete'])\n\ntype CapabilityRevisionListener = (revision: number) => void\n\nconst listeners = new Set<CapabilityRevisionListener>()\n\nexport function onCapabilityRevision(\n  listener: CapabilityRevisionListener\n): () => void {\n  listeners.add(listener)\n  return () => {\n    listeners.delete(listener)\n  }\n}\n\nfunction isMutationResponse(response: AxiosResponse | undefined): boolean {\n  const method = response?.config.method\n  return (\n    typeof method === 'string' && MUTATION_METHODS.has(method.toLowerCase())\n  )\n}\n\nfunction readCapabilityRevision(\n  response: AxiosResponse | undefined\n): number | null {\n  const headers = response?.headers\n  if (!headers) return null\n  const raw = AxiosHeaders.from(headers as RawAxiosHeaders).get(\n    CAPABILITY_REVISION_HEADER\n  )\n  const value = Array.isArray(raw) ? raw[0] : raw\n  if (typeof value !== 'string' && typeof value !== 'number') return null\n  const revision = Number(value)\n  return Number.isSafeInteger(revision) && revision > 0 ? revision : null\n}\n\n/**\n * Installs a response interceptor that republishes the capability revision a\n * mutation reports to {@link onCapabilityRevision} subscribers.\n *\n * The header is stamped before the handler runs, so a rejected mutation\n * carries it too and the error arm has to read it as well. It is absent\n * whenever CORS is bypassed (local desktop origins), so every read degrades to\n * \"no revision reported\" rather than assuming presence.\n */\nexport function attachCapabilityRevisionInterceptor(\n  client: AxiosInstance\n): void {\n  const publish = (response: AxiosResponse | undefined) => {\n    if (!isMutationResponse(response)) return\n    const revision = readCapabilityRevision(response)\n    if (revision !== null) {\n      for (const listener of Array.from(listeners)) listener(revision)\n    }\n  }\n\n  client.interceptors.response.use(\n    (response) => {\n      publish(response)\n      return response\n    },\n    (error: unknown) => {\n      publish(axios.isAxiosError(error) ? error.response : undefined)\n      throw error\n    }\n  )\n}\n","import type {\n  AxiosAdapter,\n  AxiosResponse,\n  InternalAxiosRequestConfig\n} from 'axios'\nimport axios, { AxiosError } from 'axios'\n\nimport type { WebSessionSend } from '@/platform/auth/session/webSessionFetch'\n\nfunction requestHeaders({ headers }: InternalAxiosRequestConfig): Headers {\n  const result = new Headers()\n  for (const [name, value] of Object.entries(headers.toJSON(true))) {\n    if (typeof value === 'string') result.set(name, value)\n  }\n  return result\n}\n\nfunction requestSignal({\n  signal,\n  timeout\n}: InternalAxiosRequestConfig): AbortSignal {\n  const signals: AbortSignal[] = []\n  if (signal instanceof AbortSignal) signals.push(signal)\n  if (timeout) signals.push(AbortSignal.timeout(timeout))\n  return AbortSignal.any(signals)\n}\n\nfunction statusError(\n  config: InternalAxiosRequestConfig,\n  response: AxiosResponse<string>\n): AxiosError {\n  return new AxiosError(\n    `Request failed with status code ${response.status}`,\n    response.status >= 500\n      ? AxiosError.ERR_BAD_RESPONSE\n      : AxiosError.ERR_BAD_REQUEST,\n    config,\n    undefined,\n    response\n  )\n}\n\n/** Sends an axios request on the web session and hands back the raw text. */\nexport function createWebSessionAdapter(send: WebSessionSend): AxiosAdapter {\n  return async (config) => {\n    const signal = requestSignal(config)\n    let response: Response\n    try {\n      response = await send(axios.getUri(config), {\n        method: config.method?.toUpperCase(),\n        headers: requestHeaders(config),\n        body: config.data,\n        signal\n      })\n    } catch (error) {\n      throw AxiosError.from(\n        error,\n        signal.aborted\n          ? signal.reason instanceof DOMException &&\n            signal.reason.name === 'TimeoutError'\n            ? AxiosError.ETIMEDOUT\n            : AxiosError.ERR_CANCELED\n          : AxiosError.ERR_NETWORK,\n        config\n      )\n    }\n\n    const result: AxiosResponse<string> = {\n      data: await response.text(),\n      status: response.status,\n      statusText: response.statusText,\n      headers: Object.fromEntries(response.headers),\n      config\n    }\n    if (config.validateStatus?.(result.status) === false) {\n      throw statusError(config, result)\n    }\n    return result\n  }\n}\n","import type { BillingTelemetryFailure } from '@comfyorg/account-core/billing'\n\n/**\n * A leaf module, so a subclass can be declared wherever the class is needed\n * without pulling the workspace client and its stores into the import graph.\n */\nexport class WorkspaceApiError extends Error {\n  constructor(\n    message: string,\n    public readonly status?: number,\n    public readonly code?: string,\n    /** For a failure `status` cannot classify, such as a billing SDK refusal. */\n    public readonly failureCategory?: BillingTelemetryFailure['failure_category'],\n    /** The `workspaceApi` method that failed, or the one an SDK-rail read replaces. */\n    public readonly operation?: string\n  ) {\n    super(message)\n    this.name = 'WorkspaceApiError'\n  }\n}\n\n/** Ingest's 403 code for an account left with no workspace. */\nexport const NO_WORKSPACE_ACCESS = 'no_workspace_access'\n\n/** `AcceptWorkspaceInviteErrors` 403 code, named in the spec prose only. */\nexport const MEMBERSHIP_MANAGED_BY_DIRECTORY = 'membership_managed_by_directory'\n\n/** The account can enter no workspace: ingest refused with `no_workspace_access`, or listed none. */\nexport class NoWorkspaceAccessError extends WorkspaceApiError {\n  constructor(message: string, status?: number, operation?: string) {\n    super(message, status, NO_WORKSPACE_ACCESS, undefined, operation)\n    this.name = 'NoWorkspaceAccessError'\n  }\n}\n","import type {\n  AcceptInviteResponse,\n  BillingBalanceResponse,\n  BillingCapabilitiesResponse,\n  BillingEventsResponse,\n  BillingOpStatusResponse,\n  BillingPlansResponse,\n  BillingStatus,\n  BillingStatusResponse,\n  CancelSubscriptionRequest,\n  CancelSubscriptionResponse,\n  CreateInviteRequest,\n  CreateTopupCheckoutRequest,\n  CreateTopupCheckoutResponse,\n  CreateTopupRequest,\n  CreateTopupResponse,\n  CreateWorkspaceRequest,\n  CurrentWorkspaceResponse,\n  ListInvitesResponse,\n  ListMembersResponse,\n  ListWorkspacesResponse,\n  Member as GeneratedMember,\n  PaymentPortalRequest,\n  PaymentPortalResponse,\n  PendingInvite,\n  Plan,\n  PreviewSubscribeRequest,\n  PreviewSubscribeResponse,\n  RenewalInvoice,\n  ResubscribeRequest,\n  ResubscribeResponse,\n  RetentionAcceptance,\n  RetentionAcceptRequest,\n  RetentionFlowEventRequest,\n  RetentionFlowResponse,\n  SavedPaymentMethod,\n  ScheduledPlanChange,\n  SubscribeRequest,\n  SubscribeResponse,\n  SubscriptionDuration,\n  SubscriptionTier,\n  TeamCreditStops,\n  TeamCreditStopSummary,\n  UpdateWorkspaceRequest,\n  WorkspaceWithRole\n} from '@comfyorg/ingest-types'\nimport {\n  zRetentionAcceptance,\n  zRetentionFlowResponse\n} from '@comfyorg/ingest-types/zod'\nimport type { AxiosInstance } from 'axios'\nimport axios from 'axios'\n\nimport {\n  webSessionRequests,\n  webSessionSend\n} from '@/platform/auth/session/webSessionFetch'\nimport { useTelemetry } from '@/platform/telemetry'\nimport {\n  UNKNOWN_ERROR_CODE,\n  errorResponseFromBody\n} from '@/platform/remote/comfyui/errors'\nimport { attachCapabilityRevisionInterceptor } from '@/platform/workspace/api/capabilityRevision'\nimport type {\n  WorkspaceId,\n  WorkspaceInviteId\n} from '@/platform/workspace/workspaceTypes'\nimport type { AuthHeader, UserId } from '@/types/authTypes'\n\nimport { createWebSessionAdapter } from './webSessionAdapter'\nimport {\n  NO_WORKSPACE_ACCESS,\n  NoWorkspaceAccessError,\n  WorkspaceApiError\n} from './workspaceApiError'\nimport { workspaceApiUrl } from './workspaceApiUrl'\n\nexport type WorkspaceType = 'personal' | 'team'\nexport type WorkspaceRole = 'owner' | 'member'\nexport type BillingRail = NonNullable<BillingStatusResponse['billing_rail']>\n\nexport type Member = GeneratedMember & {\n  // Per-member monthly credit limit UI (FE-1277). The cloud OpenAPI carries\n  // neither usage nor limit yet; persistence and real usage land in FE-1278.\n  credits_used_this_month?: number\n  monthly_credit_limit?: number | null\n}\n\nexport interface ListMembersParams {\n  offset?: number\n  limit?: number\n}\n\nexport type { PendingInvite }\n\nexport type { SubscriptionTier }\nexport type { SubscriptionDuration }\nexport type { WorkspaceWithRole }\nexport type { ListWorkspacesResponse }\nexport type { CurrentWorkspaceResponse }\nexport type { Plan }\nexport type { BillingPlansResponse }\nexport type { TeamCreditStops }\nexport type { TeamCreditStopSummary }\n\ntype SubscribeBillingCycle = 'monthly' | 'yearly'\n\nexport interface SubscribeOptions {\n  confirmationToken?: string\n  promotionCode?: string\n  quoteId?: string\n  quoteVersion?: number\n  savedPaymentMethodId?: string\n  returnUrl?: string\n  cancelUrl?: string\n  teamCreditStopId?: string\n  billingCycle?: SubscribeBillingCycle\n  confirmReactivation?: boolean\n  prorationAt?: string\n  /** Set when the caller reported this attempt's `billing.operation.started`; never sent to the server. */\n  attemptStartedAt?: number\n}\n\nexport interface PreviewSubscribeOptions {\n  teamCreditStopId?: string\n  promotionCode?: string\n}\n\nexport type { SubscribeResponse }\n\nexport type { PreviewSubscribeResponse }\n\nexport type BillingSubscriptionStatus = NonNullable<\n  BillingStatusResponse['subscription_status']\n>\n\nexport type { BillingStatus }\nexport type { BillingStatusResponse }\nexport type { RenewalInvoice }\nexport type { ScheduledPlanChange }\n\nexport type { BillingBalanceResponse }\nexport type { BillingEventsResponse }\nexport type { BillingCapabilitiesResponse }\nexport type { CreateTopupResponse }\nexport type { BillingOpStatusResponse }\nexport type { SavedPaymentMethod }\nexport type BillingAuthenticationState = NonNullable<\n  BillingOpStatusResponse['authentication_state']\n>\nexport type BillingDeclineReason = NonNullable<\n  BillingOpStatusResponse['decline_reason']\n>\nexport type BillingOperationPhase = NonNullable<\n  BillingOpStatusResponse['phase']\n>\nexport type BillingRecoveryAction = NonNullable<\n  BillingOpStatusResponse['recovery_action']\n>\n\ninterface GetBillingEventsParams {\n  page?: number\n  limit?: number\n}\n\nexport { WorkspaceApiError }\n\n/**\n * Credentials for workspace requests. The composition root installs the\n * auth-store backed implementation; the client itself stays free of the\n * auth layer.\n */\ninterface WorkspaceApiAuth {\n  getWorkspaceAuthHeader(): Promise<AuthHeader>\n  getFirebaseAuthHeader(): Promise<AuthHeader>\n  attachRetryInterceptor(client: AxiosInstance): void\n}\n\nconst workspaceApiClient = axios.create({\n  headers: {\n    'Content-Type': 'application/json'\n  }\n})\n\nattachCapabilityRevisionInterceptor(workspaceApiClient)\n\nlet workspaceApiAuth: WorkspaceApiAuth | undefined\n\nexport function setWorkspaceApiAuth(auth: WorkspaceApiAuth): void {\n  workspaceApiAuth = auth\n  auth.attachRetryInterceptor(workspaceApiClient)\n}\n\nfunction requireWorkspaceApiAuth(): WorkspaceApiAuth {\n  if (!workspaceApiAuth) {\n    throw new WorkspaceApiError('Workspace API auth is not installed', 401)\n  }\n  return workspaceApiAuth\n}\n\nasync function requestAuth() {\n  if (webSessionRequests()) {\n    const send = await webSessionSend()\n    if (send) return { adapter: createWebSessionAdapter(send) }\n  }\n  return { headers: await requireWorkspaceApiAuth().getWorkspaceAuthHeader() }\n}\n\nexport type WorkspaceApiOperation = keyof typeof workspaceApi\n\nfunction handleAxiosError(\n  err: unknown,\n  operation: WorkspaceApiOperation\n): never {\n  if (axios.isAxiosError(err)) {\n    const status = err.response?.status\n    const { code, message } = errorResponseFromBody(\n      err.response?.data,\n      err.message\n    )\n    if (status === 403 && code === NO_WORKSPACE_ACCESS) {\n      throw new NoWorkspaceAccessError(message, status, operation)\n    }\n    // Callers compare `code` against server-defined values, so the parser's\n    // \"no code reported\" sentinel must stay out of that contract.\n    throw new WorkspaceApiError(\n      message,\n      status,\n      code === UNKNOWN_ERROR_CODE ? undefined : code,\n      undefined,\n      operation\n    )\n  }\n  throw err\n}\n\nexport const workspaceApi = {\n  /**\n   * List all workspaces the user has access to\n   * GET /api/workspaces\n   */\n  async list(): Promise<ListWorkspacesResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<ListWorkspacesResponse>(\n        workspaceApiUrl('/workspaces'),\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'list')\n    }\n  },\n\n  /**\n   * Get the workspace bound to the current credential\n   * GET /api/workspaces/current\n   */\n  async getCurrentWorkspace(): Promise<CurrentWorkspaceResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<CurrentWorkspaceResponse>(\n        workspaceApiUrl('/workspaces/current'),\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getCurrentWorkspace')\n    }\n  },\n\n  /**\n   * Create a new workspace\n   * POST /api/workspaces\n   */\n  async create(payload: CreateWorkspaceRequest): Promise<WorkspaceWithRole> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<WorkspaceWithRole>(\n        workspaceApiUrl('/workspaces'),\n        payload,\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'create')\n    }\n  },\n\n  /**\n   * Update workspace name\n   * PATCH /api/workspaces/:id\n   */\n  async update(\n    workspaceId: WorkspaceId,\n    payload: UpdateWorkspaceRequest\n  ): Promise<WorkspaceWithRole> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.patch<WorkspaceWithRole>(\n        workspaceApiUrl(`/workspaces/${workspaceId}`),\n        payload,\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'update')\n    }\n  },\n\n  /**\n   * Delete a workspace (owner only)\n   * DELETE /api/workspaces/:id\n   */\n  async delete(workspaceId: WorkspaceId): Promise<void> {\n    const auth = await requestAuth()\n    try {\n      await workspaceApiClient.delete(\n        workspaceApiUrl(`/workspaces/${workspaceId}`),\n        auth\n      )\n    } catch (err) {\n      handleAxiosError(err, 'delete')\n    }\n  },\n\n  /**\n   * Leave the current workspace.\n   * POST /api/workspace/leave\n   */\n  async leave(): Promise<void> {\n    const auth = await requestAuth()\n    try {\n      await workspaceApiClient.post(\n        workspaceApiUrl('/workspace/leave'),\n        null,\n        auth\n      )\n    } catch (err) {\n      handleAxiosError(err, 'leave')\n    }\n  },\n\n  /**\n   * List workspace members (paginated).\n   * GET /api/workspace/members\n   */\n  async listMembers(params?: ListMembersParams): Promise<ListMembersResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<ListMembersResponse>(\n        workspaceApiUrl('/workspace/members'),\n        { ...auth, params }\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'listMembers')\n    }\n  },\n\n  /**\n   * Remove a member from the workspace.\n   * DELETE /api/workspace/members/:userId\n   */\n  async removeMember(userId: UserId): Promise<void> {\n    const auth = await requestAuth()\n    try {\n      await workspaceApiClient.delete(\n        workspaceApiUrl(`/workspace/members/${userId}`),\n        auth\n      )\n    } catch (err) {\n      handleAxiosError(err, 'removeMember')\n    }\n  },\n\n  /**\n   * Change a member's role (member ↔ owner).\n   * PATCH /api/workspace/members/:userId\n   */\n  async updateMemberRole(userId: UserId, role: WorkspaceRole): Promise<Member> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.patch<Member>(\n        workspaceApiUrl(`/workspace/members/${userId}`),\n        { role },\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'updateMemberRole')\n    }\n  },\n\n  /**\n   * List pending invites for the workspace.\n   * GET /api/workspace/invites\n   */\n  async listInvites(): Promise<ListInvitesResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<ListInvitesResponse>(\n        workspaceApiUrl('/workspace/invites'),\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'listInvites')\n    }\n  },\n\n  /**\n   * Create an invite for the workspace.\n   * POST /api/workspace/invites\n   */\n  async createInvite(payload: CreateInviteRequest): Promise<PendingInvite> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<PendingInvite>(\n        workspaceApiUrl('/workspace/invites'),\n        payload,\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'createInvite')\n    }\n  },\n\n  /**\n   * Revoke a pending invite.\n   * DELETE /api/workspace/invites/:inviteId\n   */\n  async revokeInvite(inviteId: WorkspaceInviteId): Promise<void> {\n    const auth = await requestAuth()\n    try {\n      await workspaceApiClient.delete(\n        workspaceApiUrl(`/workspace/invites/${inviteId}`),\n        auth\n      )\n    } catch (err) {\n      handleAxiosError(err, 'revokeInvite')\n    }\n  },\n\n  async resendInvite(inviteId: WorkspaceInviteId): Promise<PendingInvite> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<PendingInvite>(\n        workspaceApiUrl(\n          `/workspace/invites/${encodeURIComponent(inviteId)}/resend`\n        ),\n        null,\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'resendInvite')\n    }\n  },\n\n  /**\n   * Accept a workspace invite.\n   * POST /api/invites/:token/accept\n   * Uses Firebase auth (user identity) since the user isn't yet a workspace member.\n   */\n  async acceptInvite(token: string): Promise<AcceptInviteResponse> {\n    const headers = await requireWorkspaceApiAuth().getFirebaseAuthHeader()\n    try {\n      const response = await workspaceApiClient.post<AcceptInviteResponse>(\n        workspaceApiUrl(`/invites/${token}/accept`),\n        null,\n        { headers, __skipUnifiedRemint: true }\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'acceptInvite')\n    }\n  },\n\n  /**\n   * Get billing status for the current workspace\n   * GET /api/billing/status\n   */\n  async getBillingStatus(): Promise<BillingStatusResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<BillingStatusResponse>(\n        workspaceApiUrl('/billing/status'),\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getBillingStatus')\n    }\n  },\n\n  /**\n   * Get credit balance for the current workspace\n   * GET /api/billing/balance\n   */\n  async getBillingBalance(): Promise<BillingBalanceResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<BillingBalanceResponse>(\n        workspaceApiUrl('/billing/balance'),\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getBillingBalance')\n    }\n  },\n\n  /**\n   * Get billing capabilities for the current workspace\n   * GET /api/billing/capabilities\n   */\n  async getBillingCapabilities(\n    signal?: AbortSignal\n  ): Promise<BillingCapabilitiesResponse> {\n    const auth = await requestAuth()\n    try {\n      const response =\n        await workspaceApiClient.get<BillingCapabilitiesResponse>(\n          workspaceApiUrl('/billing/capabilities'),\n          { ...auth, timeout: 10_000, signal }\n        )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getBillingCapabilities')\n    }\n  },\n\n  /**\n   * Get available subscription plans\n   * GET /api/billing/plans\n   */\n  async getBillingPlans(): Promise<BillingPlansResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<BillingPlansResponse>(\n        workspaceApiUrl('/billing/plans'),\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getBillingPlans')\n    }\n  },\n\n  async listSavedPaymentMethods(): Promise<SavedPaymentMethod[]> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<SavedPaymentMethod[]>(\n        workspaceApiUrl('/billing/payment-methods'),\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'listSavedPaymentMethods')\n    }\n  },\n\n  /**\n   * Preview subscription change\n   * POST /api/billing/preview-subscribe\n   */\n  async previewSubscribe(\n    planSlug: string,\n    options: PreviewSubscribeOptions = {}\n  ): Promise<PreviewSubscribeResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<PreviewSubscribeResponse>(\n        workspaceApiUrl('/billing/preview-subscribe'),\n        {\n          plan_slug: planSlug,\n          team_credit_stop_id: options.teamCreditStopId,\n          promotion_code: options.promotionCode\n        } satisfies PreviewSubscribeRequest,\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'previewSubscribe')\n    }\n  },\n\n  /**\n   * Subscribe to a billing plan\n   * POST /api/billing/subscribe\n   */\n  async subscribe(\n    planSlug: string,\n    options: SubscribeOptions = {}\n  ): Promise<SubscribeResponse> {\n    if (\n      options.confirmationToken !== undefined &&\n      options.savedPaymentMethodId !== undefined\n    ) {\n      throw new TypeError(\n        'confirmationToken and savedPaymentMethodId are mutually exclusive'\n      )\n    }\n    // JSON drops `undefined` but keeps `''`, so an empty credential would reach\n    // the API as a present-but-meaningless value.\n    const confirmationToken = options.confirmationToken || undefined\n    const savedPaymentMethodId = options.savedPaymentMethodId || undefined\n    const auth = await requestAuth()\n    try {\n      useTelemetry()?.trackBillingEvent({\n        operation: 'subscription_checkout',\n        stage: 'request_sent',\n        outcome: 'pending'\n      })\n      const response = await workspaceApiClient.post<SubscribeResponse>(\n        workspaceApiUrl('/billing/subscribe'),\n        {\n          plan_slug: planSlug,\n          confirmation_token: confirmationToken,\n          promotion_code: options.promotionCode,\n          quote_id: options.quoteId,\n          quote_version: options.quoteVersion,\n          saved_payment_method_id: savedPaymentMethodId,\n          return_url: options.returnUrl,\n          cancel_url: options.cancelUrl,\n          team_credit_stop_id: options.teamCreditStopId,\n          billing_cycle: options.billingCycle,\n          confirm_reactivation: options.confirmReactivation,\n          proration_at: options.prorationAt\n        } satisfies SubscribeRequest,\n        auth\n      )\n      useTelemetry()?.trackBillingEvent({\n        operation: 'subscription_checkout',\n        stage: 'checkout_received',\n        outcome: 'pending',\n        billing_op_id: response.data.billing_op_id,\n        checkout_status: response.data.status\n      })\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'subscribe')\n    }\n  },\n\n  /**\n   * Cancel current subscription\n   * POST /api/billing/subscription/cancel\n   */\n  async cancelSubscription(\n    idempotencyKey?: string\n  ): Promise<CancelSubscriptionResponse> {\n    const auth = await requestAuth()\n    try {\n      const response =\n        await workspaceApiClient.post<CancelSubscriptionResponse>(\n          workspaceApiUrl('/billing/subscription/cancel'),\n          {\n            idempotency_key: idempotencyKey\n          } satisfies CancelSubscriptionRequest,\n          auth\n        )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'cancelSubscription')\n    }\n  },\n\n  /**\n   * Prepare a cancellation session and any retention offer for its owner\n   * POST /api/billing/retention/prepare\n   */\n  async prepareRetentionFlow(): Promise<RetentionFlowResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<unknown>(\n        workspaceApiUrl('/billing/retention/prepare'),\n        {},\n        { ...auth, timeout: 5_000 }\n      )\n      return zRetentionFlowResponse.parse(response.data)\n    } catch (err) {\n      handleAxiosError(err, 'prepareRetentionFlow')\n    }\n  },\n\n  /**\n   * Accept the offer bound to a cancellation session\n   * POST /api/billing/retention/accept\n   */\n  async acceptRetentionOffer(sessionId: string): Promise<RetentionAcceptance> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<unknown>(\n        workspaceApiUrl('/billing/retention/accept'),\n        { session_id: sessionId } satisfies RetentionAcceptRequest,\n        auth\n      )\n      return zRetentionAcceptance.parse(response.data)\n    } catch (err) {\n      handleAxiosError(err, 'acceptRetentionOffer')\n    }\n  },\n\n  /**\n   * Record that a cancellation session opened, or displayed its offer\n   * POST /api/billing/retention/events\n   */\n  async recordRetentionFlowEvent(\n    request: RetentionFlowEventRequest\n  ): Promise<void> {\n    const auth = await requestAuth()\n    try {\n      await workspaceApiClient.post(\n        workspaceApiUrl('/billing/retention/events'),\n        request,\n        auth\n      )\n    } catch (err) {\n      handleAxiosError(err, 'recordRetentionFlowEvent')\n    }\n  },\n\n  /**\n   * Resubscribe (undo cancel) before period ends\n   * POST /api/billing/subscription/resubscribe\n   */\n  async resubscribe(idempotencyKey?: string): Promise<ResubscribeResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<ResubscribeResponse>(\n        workspaceApiUrl('/billing/subscription/resubscribe'),\n        { idempotency_key: idempotencyKey } satisfies ResubscribeRequest,\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'resubscribe')\n    }\n  },\n\n  /**\n   * Get Stripe payment portal URL for managing payment methods\n   * POST /api/billing/payment-portal\n   */\n  async getPaymentPortalUrl(\n    returnUrl?: string\n  ): Promise<PaymentPortalResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.post<PaymentPortalResponse>(\n        workspaceApiUrl('/billing/payment-portal'),\n        { return_url: returnUrl } satisfies PaymentPortalRequest,\n        auth\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getPaymentPortalUrl')\n    }\n  },\n\n  /**\n   * Create a credit top-up\n   * POST /api/billing/topup\n   */\n  async createTopup(\n    amountCents: number,\n    idempotencyKey?: string\n  ): Promise<CreateTopupResponse> {\n    const auth = await requestAuth()\n    try {\n      useTelemetry()?.trackBillingEvent({\n        operation: 'topup',\n        stage: 'request_sent',\n        outcome: 'pending'\n      })\n      const response = await workspaceApiClient.post<CreateTopupResponse>(\n        workspaceApiUrl('/billing/topup'),\n        {\n          amount_cents: amountCents,\n          idempotency_key: idempotencyKey\n        } satisfies CreateTopupRequest,\n        auth\n      )\n      useTelemetry()?.trackBillingEvent({\n        operation: 'topup',\n        stage: 'checkout_received',\n        outcome: 'pending',\n        billing_op_id: response.data.billing_op_id,\n        checkout_status: response.data.status\n      })\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'createTopup')\n    }\n  },\n\n  /**\n   * Create a Stripe-hosted credit top-up checkout session\n   * POST /api/billing/topup/checkout\n   */\n  async createTopupCheckout(\n    amountCents: number,\n    returnUrl: string\n  ): Promise<CreateTopupCheckoutResponse> {\n    const auth = await requestAuth()\n    try {\n      const response =\n        await workspaceApiClient.post<CreateTopupCheckoutResponse>(\n          workspaceApiUrl('/billing/topup/checkout'),\n          {\n            amount_cents: amountCents,\n            return_url: returnUrl,\n            idempotency_key: crypto.randomUUID()\n          } satisfies CreateTopupCheckoutRequest,\n          auth\n        )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'createTopupCheckout')\n    }\n  },\n\n  /**\n   * Get billing events\n   * GET /api/billing/events\n   */\n  async getBillingEvents(\n    params?: GetBillingEventsParams\n  ): Promise<BillingEventsResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<BillingEventsResponse>(\n        workspaceApiUrl('/billing/events'),\n        { ...auth, params }\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getBillingEvents')\n    }\n  },\n\n  /**\n   * Get billing operation status\n   * GET /api/billing/ops/:id\n   */\n  async getBillingOpStatus(opId: string): Promise<BillingOpStatusResponse> {\n    const auth = await requestAuth()\n    try {\n      const response = await workspaceApiClient.get<BillingOpStatusResponse>(\n        workspaceApiUrl(`/billing/ops/${encodeURIComponent(opId)}`),\n        { ...auth, timeout: 30_000 }\n      )\n      return response.data\n    } catch (err) {\n      handleAxiosError(err, 'getBillingOpStatus')\n    }\n  }\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref, shallowRef, watch } from 'vue'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  desktopHostUser,\n  isDesktopHostSignedIn,\n  requestDesktopHostWorkspaceSwitch\n} from '@/platform/auth/desktopHost/desktopHostSession'\nimport { trackSsoWorkspaceLanded } from '@/platform/auth/sso/ssoTelemetry'\nimport { isCloud } from '@/platform/distribution/types'\nimport { WORKSPACE_STORAGE_KEYS } from '@/platform/workspace/workspaceConstants'\nimport { clearPreservedQuery } from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport {\n  clearWorkflowRestoreState,\n  prepareWorkflowWorkspaceTransition\n} from '@/platform/workflow/persistence/base/storageIO'\nimport { useWorkspaceAuthStore } from '@/platform/workspace/stores/workspaceAuthStore'\n\nimport type {\n  BillingRail,\n  CurrentWorkspaceResponse,\n  ListMembersParams,\n  ListWorkspacesResponse,\n  Member,\n  PendingInvite as ApiPendingInvite,\n  SubscriptionTier,\n  WorkspaceWithRole\n} from '../api/workspaceApi'\nimport { WorkspaceApiError, workspaceApi } from '../api/workspaceApi'\nimport { NoWorkspaceAccessError } from '../api/workspaceApiError'\n\nexport interface WorkspaceMember {\n  id: string\n  name: string\n  email: string\n  joinDate: Date\n  role: 'owner' | 'member'\n  isOriginalOwner: boolean\n  creditsUsedThisMonth?: number\n  monthlyCreditLimit?: number | null\n}\n\nexport interface WorkspacePendingInvite {\n  id: string\n  email: string\n  inviteDate: Date\n  expiryDate: Date\n  /**\n   * Invite token for building shareable invite links.\n   * Absent/empty for expired invites (the backend omits it).\n   */\n  token?: string\n}\n\ntype SubscriptionPlan = string | null\n\ninterface WorkspaceState extends WorkspaceWithRole {\n  isSubscribed: boolean\n  subscriptionPlan: SubscriptionPlan\n  subscriptionTier: SubscriptionTier | null\n  members: WorkspaceMember[]\n  membersLoaded: boolean\n  totalMembers?: number\n  pendingInvites: WorkspacePendingInvite[]\n  pendingInvitesLoaded: boolean\n}\n\ntype InitState = 'uninitialized' | 'loading' | 'ready' | 'error'\n\nfunction mapApiMemberToWorkspaceMember(member: Member): WorkspaceMember {\n  return {\n    id: member.id,\n    name: member.name,\n    email: member.email,\n    joinDate: new Date(member.joined_at),\n    role: member.role,\n    isOriginalOwner: member.is_original_owner,\n    creditsUsedThisMonth: member.credits_used_this_month,\n    monthlyCreditLimit: member.monthly_credit_limit\n  }\n}\n\nfunction mapApiInviteToPendingInvite(\n  invite: ApiPendingInvite\n): WorkspacePendingInvite {\n  return {\n    id: invite.id,\n    email: invite.email,\n    inviteDate: new Date(invite.invited_at),\n    expiryDate: new Date(invite.expires_at),\n    token: invite.token\n  }\n}\n\nfunction createWorkspaceState(workspace: WorkspaceWithRole): WorkspaceState {\n  return {\n    ...workspace,\n    // Personal workspaces use user-scoped subscription from useSubscription()\n    isSubscribed:\n      workspace.type === 'personal' || !!workspace.subscription_tier,\n    subscriptionPlan: null,\n    subscriptionTier: workspace.subscription_tier ?? null,\n    members: [],\n    membersLoaded: false,\n    pendingInvites: [],\n    pendingInvitesLoaded: false\n  }\n}\n\n/**\n * Builds workspace state from GET /api/workspaces/current — the single\n * workspace bound to an API-key credential. The response carries no\n * membership timestamps (only sortWorkspaces reads them, and a one-entry list\n * never sorts) and may omit role, which fails closed to member so owner-only\n * billing actions stay hidden rather than 403 on click.\n */\nfunction createWorkspaceStateFromCredential(\n  current: CurrentWorkspaceResponse\n): WorkspaceState {\n  return createWorkspaceState({\n    id: current.id,\n    name: current.name,\n    type: current.type,\n    role: current.role ?? 'member',\n    created_at: '',\n    joined_at: ''\n  })\n}\n\nexport function sortWorkspaces<T extends WorkspaceWithRole>(list: T[]): T[] {\n  return [...list].sort((a, b) => {\n    if (a.type === 'personal') return -1\n    if (b.type === 'personal') return 1\n    const dateA = a.role === 'owner' ? a.created_at : a.joined_at\n    const dateB = b.role === 'owner' ? b.created_at : b.joined_at\n    return dateA.localeCompare(dateB)\n  })\n}\n\nfunction getLastWorkspaceId(): string | null {\n  try {\n    return localStorage.getItem(WORKSPACE_STORAGE_KEYS.LAST_WORKSPACE_ID)\n  } catch {\n    return null\n  }\n}\n\nfunction setLastWorkspaceId(workspaceId: string): void {\n  try {\n    localStorage.setItem(WORKSPACE_STORAGE_KEYS.LAST_WORKSPACE_ID, workspaceId)\n  } catch {\n    console.warn('Failed to persist last workspace ID to localStorage')\n  }\n}\n\n/** The workspace a switch reloads into, read once by the next initialization. */\nfunction setSwitchTargetId(workspaceId: string): void {\n  try {\n    sessionStorage.setItem(WORKSPACE_STORAGE_KEYS.SWITCH_TARGET_ID, workspaceId)\n  } catch {\n    console.warn('Failed to persist the workspace switch target')\n  }\n}\n\nfunction takeSwitchTargetId(): string | null {\n  try {\n    const id = sessionStorage.getItem(WORKSPACE_STORAGE_KEYS.SWITCH_TARGET_ID)\n    sessionStorage.removeItem(WORKSPACE_STORAGE_KEYS.SWITCH_TARGET_ID)\n    return id\n  } catch {\n    return null\n  }\n}\n\nfunction clearLastWorkspaceId(): void {\n  try {\n    localStorage.removeItem(WORKSPACE_STORAGE_KEYS.LAST_WORKSPACE_ID)\n  } catch {\n    console.warn('Failed to clear last workspace ID from localStorage')\n  }\n}\n\n/** An ingest deployed before `can_create_workspace` omits it; only an explicit false refuses. */\ntype ListedWorkspaces = Omit<ListWorkspacesResponse, 'can_create_workspace'> &\n  Partial<Pick<ListWorkspacesResponse, 'can_create_workspace'>> & {\n    /** The SSO organization's workspace a sign-in opens (cloud#12614). */\n    default_workspace_id?: string\n  }\n\nfunction reportSsoLanding(\n  { default_workspace_id }: ListedWorkspaces,\n  workspaceId: string\n): void {\n  trackSsoWorkspaceLanded(\n    !!default_workspace_id && workspaceId === default_workspace_id\n  )\n}\n\nconst MAX_OWNED_WORKSPACES = 10\nconst MAX_INIT_RETRIES = 3\nconst BASE_RETRY_DELAY_MS = 1000\n\nexport const useTeamWorkspaceStore = defineStore('teamWorkspace', () => {\n  const { flags } = useFeatureFlags()\n  const initState = ref<InitState>('uninitialized')\n  const workspaces = shallowRef<WorkspaceState[]>([])\n  const mutableActiveWorkspaceId = ref<string | null>(null)\n  const activeWorkspaceId = computed(() => mutableActiveWorkspaceId.value)\n  const billingRailByWorkspaceId = shallowRef<Record<string, BillingRail>>({})\n  const error = ref<Error | null>(null)\n\n  const isCreating = ref(false)\n  const isDeleting = ref(false)\n  const isSwitching = ref(false)\n  const isFetchingWorkspaces = ref(false)\n  const mutableWorkspaceTransitionGeneration = ref(0)\n  const workspaceTransitionGeneration = computed(\n    () => mutableWorkspaceTransitionGeneration.value\n  )\n  let identityGeneration = 0\n  let initializationPromise: Promise<void> | null = null\n  let pendingWorkspaceSwitch: Promise<void> | null = null\n\n  function isStaleIdentity(generation: number): boolean {\n    return generation !== identityGeneration\n  }\n\n  function isStaleWorkspace(generation: number, workspaceId: string): boolean {\n    return (\n      isStaleIdentity(generation) || activeWorkspaceId.value !== workspaceId\n    )\n  }\n\n  const activeWorkspace = computed(\n    () => workspaces.value.find((w) => w.id === activeWorkspaceId.value) ?? null\n  )\n\n  const personalWorkspace = computed(\n    () => workspaces.value.find((w) => w.type === 'personal') ?? null\n  )\n\n  const isInPersonalWorkspace = computed(\n    () => activeWorkspace.value?.type === 'personal'\n  )\n\n  const activeWorkspaceBillingRail = computed(() => {\n    const workspaceId = activeWorkspaceId.value\n    return workspaceId\n      ? (billingRailByWorkspaceId.value[workspaceId] ?? null)\n      : null\n  })\n\n  const sharedWorkspaces = computed(() =>\n    workspaces.value.filter((w) => w.type !== 'personal')\n  )\n\n  const ownedWorkspacesCount = computed(\n    () => workspaces.value.filter((w) => w.role === 'owner').length\n  )\n\n  /** The server says an SSO organization manages this account's workspaces. */\n  const workspacesManagedByOrganization = ref(false)\n\n  const canCreateWorkspace = computed(\n    () =>\n      !workspacesManagedByOrganization.value &&\n      ownedWorkspacesCount.value < MAX_OWNED_WORKSPACES\n  )\n\n  function applyWorkspaceList(response: ListedWorkspaces): void {\n    workspaces.value = sortWorkspaces(\n      response.workspaces.map(createWorkspaceState)\n    )\n    workspacesManagedByOrganization.value =\n      response.can_create_workspace === false\n  }\n\n  const members = computed<WorkspaceMember[]>(\n    () => activeWorkspace.value?.members ?? []\n  )\n\n  const membersLoaded = computed(\n    () => activeWorkspace.value?.membersLoaded ?? false\n  )\n\n  // The active workspace's original owner (creator). Prefers the\n  // `is_original_owner` flag; without it, falls back to the earliest-joined\n  // owner — never a plain member, who must stay role-changeable.\n  const originalOwnerId = computed<string | null>(() => {\n    const flagged = members.value.find((m) => m.isOriginalOwner)\n    if (flagged) return flagged.id\n    const owners = members.value.filter((m) => m.role === 'owner')\n    if (owners.length === 0) return null\n    return owners.reduce((earliest, m) =>\n      m.joinDate < earliest.joinDate ? m : earliest\n    ).id\n  })\n\n  // True when the current user is that original owner. Single-sourced from\n  // `originalOwnerId` so the two creator signals can never disagree. Matches the\n  // self-row by email (the stable current-user join key; member.id is a cloud\n  // user id, not the Firebase uid) and fails closed until members load.\n  const isCurrentUserOriginalOwner = computed(() => {\n    const email = useCurrentUser().userEmail.value?.toLowerCase()\n    if (!email) return false\n    const selfRow = members.value.find((m) => m.email.toLowerCase() === email)\n    return !!selfRow && selfRow.id === originalOwnerId.value\n  })\n\n  const pendingInvites = computed<WorkspacePendingInvite[]>(\n    () => activeWorkspace.value?.pendingInvites ?? []\n  )\n\n  const pendingInvitesLoaded = computed(\n    () => activeWorkspace.value?.pendingInvitesLoaded ?? false\n  )\n\n  const workspaceId = computed(() => activeWorkspace.value?.id ?? null)\n\n  const workspaceName = computed(() => activeWorkspace.value?.name ?? '')\n\n  const isWorkspaceSubscribed = computed(\n    () => activeWorkspace.value?.isSubscribed ?? false\n  )\n\n  const subscriptionPlan = computed(\n    () => activeWorkspace.value?.subscriptionPlan ?? null\n  )\n\n  function updateWorkspace(\n    workspaceId: string,\n    updates: Partial<WorkspaceState>\n  ) {\n    const index = workspaces.value.findIndex((w) => w.id === workspaceId)\n    if (index === -1) return\n\n    const current = workspaces.value[index]\n    const updated = { ...current, ...updates }\n    workspaces.value = [\n      ...workspaces.value.slice(0, index),\n      updated,\n      ...workspaces.value.slice(index + 1)\n    ]\n  }\n\n  function updateActiveWorkspace(updates: Partial<WorkspaceState>) {\n    if (!activeWorkspaceId.value) return\n    updateWorkspace(activeWorkspaceId.value, updates)\n  }\n\n  function setWorkspaceBillingRail(\n    workspaceId: string,\n    billingRail: BillingRail\n  ) {\n    billingRailByWorkspaceId.value = {\n      ...billingRailByWorkspaceId.value,\n      [workspaceId]: billingRail\n    }\n  }\n\n  /**\n   * Initialize the workspace store.\n   * Fetches workspaces and resolves the active workspace from session/localStorage.\n   * Delegates token management to workspaceAuthStore.\n   * Retries on transient failures with exponential backoff.\n   * Call once on app boot.\n   */\n  async function performInitialization(): Promise<void> {\n    const generation = identityGeneration\n    initState.value = 'loading'\n    isFetchingWorkspaces.value = true\n    error.value = null\n\n    const workspaceAuthStore = useWorkspaceAuthStore()\n    const isApiKeySession = useCurrentUser().isApiKeyLogin.value\n\n    for (let attempt = 0; attempt <= MAX_INIT_RETRIES; attempt++) {\n      try {\n        // An API-key credential is bound to exactly one workspace on the\n        // server. There is no discovery, switching, or token exchange for it:\n        // the server echoes the binding back and the key itself authenticates\n        // workspace-scoped calls.\n        // Desktop owns a host session's workspace: list what the account can\n        // reach and follow the workspace Desktop's session is scoped to.\n        if (isDesktopHostSignedIn()) {\n          const response = await workspaceApi.list()\n          if (isStaleIdentity(generation)) return\n          applyWorkspaceList(response)\n          const hostWorkspaceId = desktopHostUser.value?.workspaceId\n          if (!workspaces.value.some((w) => w.id === hostWorkspaceId)) {\n            throw new NoWorkspaceAccessError('Desktop workspace not available')\n          }\n          mutableActiveWorkspaceId.value = hostWorkspaceId ?? null\n          initState.value = 'ready'\n          isFetchingWorkspaces.value = false\n          return\n        }\n\n        if (isApiKeySession) {\n          const current = await workspaceApi.getCurrentWorkspace()\n          if (isStaleIdentity(generation)) return\n          workspaces.value = [createWorkspaceStateFromCredential(current)]\n          mutableActiveWorkspaceId.value = current.id\n          initState.value = 'ready'\n          isFetchingWorkspaces.value = false\n          return\n        }\n\n        const { useSessionCookie } =\n          await import('@/platform/auth/session/useSessionCookie')\n        await useSessionCookie().ensureSessionCookie()\n        if (isStaleIdentity(generation)) return\n\n        // 1. Try to restore workspace context from session (page refresh case)\n        const hasValidSession = workspaceAuthStore.initializeFromSession()\n\n        if (hasValidSession && workspaceAuthStore.currentWorkspace) {\n          // Valid session exists - fetch workspace list and verify access\n          const response = await workspaceApi.list()\n          if (isStaleIdentity(generation)) return\n          applyWorkspaceList(response)\n\n          if (workspaces.value.length === 0) {\n            throw new NoWorkspaceAccessError('No workspaces available')\n          }\n\n          // Verify session workspace exists in fetched list\n          const sessionWorkspaceId = workspaceAuthStore.currentWorkspace.id\n          const sessionWorkspaceExists = workspaces.value.some(\n            (w) => w.id === sessionWorkspaceId\n          )\n\n          if (sessionWorkspaceExists) {\n            mutableActiveWorkspaceId.value = sessionWorkspaceId\n            reportSsoLanding(response, sessionWorkspaceId)\n            initState.value = 'ready'\n            isFetchingWorkspaces.value = false\n            return\n          }\n\n          // Session workspace not found (deleted/access revoked) - fallback to default\n          if (isCloud) clearWorkflowRestoreState()\n          workspaceAuthStore.clearWorkspaceContext()\n\n          const personal = workspaces.value.find((w) => w.type === 'personal')\n          const fallbackWorkspaceId = personal?.id ?? workspaces.value[0].id\n\n          await workspaceAuthStore.switchWorkspace(fallbackWorkspaceId)\n\n          if (isStaleIdentity(generation)) return\n\n          mutableActiveWorkspaceId.value = fallbackWorkspaceId\n          setLastWorkspaceId(fallbackWorkspaceId)\n          reportSsoLanding(response, fallbackWorkspaceId)\n          initState.value = 'ready'\n          isFetchingWorkspaces.value = false\n          return\n        }\n\n        // 2. No valid session - fetch workspaces and pick default\n        const response: ListedWorkspaces = await workspaceApi.list()\n        if (isStaleIdentity(generation)) return\n        applyWorkspaceList(response)\n\n        if (workspaces.value.length === 0) {\n          throw new NoWorkspaceAccessError('No workspaces available')\n        }\n\n        // 3. Determine target workspace (priority: a switch's target >\n        // the server's default > localStorage > personal)\n        const listed = (id: string | null | undefined): id is string =>\n          !!id && workspaces.value.some((w) => w.id === id)\n        let targetWorkspaceId: string | null =\n          [\n            takeSwitchTargetId(),\n            response.default_workspace_id,\n            getLastWorkspaceId()\n          ].find(listed) ?? null\n\n        if (!targetWorkspaceId) {\n          const personal = workspaces.value.find((w) => w.type === 'personal')\n          targetWorkspaceId = personal?.id ?? workspaces.value[0].id\n        }\n\n        // 4. Exchange Firebase token for workspace token\n        await workspaceAuthStore.switchWorkspace(targetWorkspaceId)\n\n        if (isStaleIdentity(generation)) return\n\n        // 5. Set active workspace\n        mutableActiveWorkspaceId.value = targetWorkspaceId\n        setLastWorkspaceId(targetWorkspaceId)\n        reportSsoLanding(response, targetWorkspaceId)\n\n        initState.value = 'ready'\n        isFetchingWorkspaces.value = false\n        return\n      } catch (e) {\n        if (isStaleIdentity(generation)) return\n        // With SSO off, ingest's 403 keeps today's retries.\n        const isNoWorkspacesError =\n          e instanceof NoWorkspaceAccessError &&\n          (e.status === undefined || flags.ssoEnabled)\n        // A definitive 4xx on the credential lookup cannot be repaired by\n        // resending the same key; retries stay reserved for transient\n        // failures (network, 408/429, 5xx).\n        const isPermanentCredentialError =\n          isApiKeySession &&\n          e instanceof WorkspaceApiError &&\n          e.status !== undefined &&\n          e.status >= 400 &&\n          e.status < 500 &&\n          e.status !== 408 &&\n          e.status !== 429\n\n        // Don't retry on permanent errors (no workspaces available)\n        if (\n          isNoWorkspacesError ||\n          isPermanentCredentialError ||\n          attempt >= MAX_INIT_RETRIES\n        ) {\n          error.value = e instanceof Error ? e : new Error('Unknown error')\n          initState.value = 'error'\n          isFetchingWorkspaces.value = false\n          throw e\n        }\n\n        // Retry with exponential backoff for transient errors\n        const delay = BASE_RETRY_DELAY_MS * Math.pow(2, attempt)\n        const errorMessage = e instanceof Error ? e.message : String(e)\n        console.warn(\n          `[teamWorkspaceStore] Init failed (attempt ${attempt + 1}/${MAX_INIT_RETRIES + 1}), retrying in ${delay}ms: ${errorMessage}`\n        )\n        await new Promise((resolve) => setTimeout(resolve, delay))\n        if (isStaleIdentity(generation)) return\n      }\n    }\n\n    if (isStaleIdentity(generation)) return\n    isFetchingWorkspaces.value = false\n  }\n\n  function initialize(): Promise<void> {\n    if (initializationPromise) return initializationPromise\n    if (initState.value !== 'uninitialized' && initState.value !== 'error') {\n      return Promise.resolve()\n    }\n\n    const promise = performInitialization()\n    initializationPromise = promise\n    void promise.then(\n      () => {\n        if (initializationPromise === promise) initializationPromise = null\n      },\n      () => {\n        if (initializationPromise === promise) initializationPromise = null\n      }\n    )\n    return promise\n  }\n\n  /**\n   * Re-fetch workspaces from API without changing active workspace.\n   */\n  async function refreshWorkspaces(): Promise<void> {\n    const generation = identityGeneration\n    isFetchingWorkspaces.value = true\n    try {\n      const response = await workspaceApi.list()\n      if (isStaleIdentity(generation)) return\n      applyWorkspaceList(response)\n    } finally {\n      if (!isStaleIdentity(generation)) {\n        isFetchingWorkspaces.value = false\n      }\n    }\n  }\n\n  /** Returns whether the revoked workspace was handled, with or without reload. */\n  function forgetRevokedActiveWorkspace(workspaceId: string): boolean {\n    if (activeWorkspaceId.value !== workspaceId) return false\n\n    const revoked = workspaces.value.find((w) => w.id === workspaceId)\n    if (revoked?.type === 'personal') return true\n\n    if (!isCloud) {\n      const personal = workspaces.value.find((w) => w.type === 'personal')\n      workspaces.value = workspaces.value.filter((w) => w.id !== workspaceId)\n      mutableActiveWorkspaceId.value = personal?.id ?? null\n      if (personal) {\n        setLastWorkspaceId(personal.id)\n      } else {\n        clearLastWorkspaceId()\n      }\n      return true\n    }\n\n    prepareWorkflowWorkspaceTransition()\n    clearLastWorkspaceId()\n    window.location.reload()\n    return true\n  }\n\n  /**\n   * Switch to a different workspace.\n   * Clears workspace context and reloads the page.\n   */\n  async function executeWorkspaceSwitch(workspaceId: string): Promise<void> {\n    const generation = identityGeneration\n    const workspaceAuthStore = useWorkspaceAuthStore()\n\n    mutableWorkspaceTransitionGeneration.value++\n    isSwitching.value = true\n\n    try {\n      // Verify workspace exists in our list (user has access)\n      const workspace = workspaces.value.find((w) => w.id === workspaceId)\n      if (!workspace) {\n        // Workspace not in list - try refetching in case it was added\n        await refreshWorkspaces()\n        if (isStaleIdentity(generation)) return\n        const refreshedWorkspace = workspaces.value.find(\n          (w) => w.id === workspaceId\n        )\n        if (!refreshedWorkspace) {\n          throw new Error('Workspace not found or access denied')\n        }\n      }\n\n      if (isStaleIdentity(generation)) return\n\n      if (!isCloud) {\n        const switched = isDesktopHostSignedIn()\n          ? await requestDesktopHostWorkspaceSwitch(workspaceId)\n          : await workspaceAuthStore\n              .switchWorkspace(workspaceId)\n              .then(\n                () => workspaceAuthStore.currentWorkspace?.id === workspaceId\n              )\n        if (isStaleIdentity(generation)) return\n        if (!switched) {\n          throw new Error('Workspace authentication did not switch')\n        }\n        mutableActiveWorkspaceId.value = workspaceId\n        setLastWorkspaceId(workspaceId)\n        isSwitching.value = false\n        return\n      }\n\n      prepareWorkflowWorkspaceTransition()\n      workspaceAuthStore.clearWorkspaceContext()\n      setLastWorkspaceId(workspaceId)\n      setSwitchTargetId(workspaceId)\n\n      // Reload to reinitialize with new workspace\n      window.location.reload()\n      // Code after this won't run (page reloads)\n    } catch (e) {\n      if (!isStaleIdentity(generation)) {\n        isSwitching.value = false\n      }\n      throw e\n    }\n  }\n\n  async function switchWorkspace(workspaceId: string): Promise<void> {\n    if (workspaceId === activeWorkspaceId.value) return\n    if (!isCloud && isSwitching.value) {\n      console.error('Workspace switch already in progress')\n      return\n    }\n\n    const workspaceSwitch = executeWorkspaceSwitch(workspaceId)\n    pendingWorkspaceSwitch = workspaceSwitch\n    try {\n      await workspaceSwitch\n    } finally {\n      if (pendingWorkspaceSwitch === workspaceSwitch) {\n        pendingWorkspaceSwitch = null\n      }\n    }\n  }\n\n  function waitForWorkspaceSwitch(): Promise<void> {\n    return pendingWorkspaceSwitch ?? Promise.resolve()\n  }\n\n  /**\n   * Create a new workspace and switch to it.\n   */\n  async function createWorkspace(name: string): Promise<WorkspaceState> {\n    const generation = identityGeneration\n    const workspaceAuthStore = useWorkspaceAuthStore()\n\n    isCreating.value = true\n\n    try {\n      const newWorkspace = await workspaceApi.create({ name })\n      const workspaceState = createWorkspaceState(newWorkspace)\n      if (isStaleIdentity(generation)) return workspaceState\n\n      // Add to local list\n      workspaces.value = [...workspaces.value, workspaceState]\n\n      // Clear context and switch to new workspace\n      prepareWorkflowWorkspaceTransition()\n      workspaceAuthStore.clearWorkspaceContext()\n      // Clear any preserved invite query to prevent stale invites from being\n      // processed after the reload (prevents owner adding themselves as member)\n      clearPreservedQuery(PRESERVED_QUERY_NAMESPACES.INVITE)\n      setLastWorkspaceId(newWorkspace.id)\n      window.location.reload()\n\n      // Code after this won't run (page reloads)\n      return workspaceState\n    } catch (e) {\n      if (!isStaleIdentity(generation)) {\n        isCreating.value = false\n      }\n      throw e\n    }\n  }\n\n  /**\n   * Delete a workspace.\n   * If deleting active workspace, switches to personal.\n   */\n  async function deleteWorkspace(workspaceId?: string): Promise<void> {\n    const generation = identityGeneration\n    const targetId = workspaceId ?? activeWorkspaceId.value\n    if (!targetId) throw new Error('No workspace to delete')\n\n    const workspace = workspaces.value.find((w) => w.id === targetId)\n    if (!workspace) throw new Error('Workspace not found')\n    if (workspace.type === 'personal') {\n      throw new Error('Cannot delete personal workspace')\n    }\n\n    const workspaceAuthStore = useWorkspaceAuthStore()\n\n    isDeleting.value = true\n\n    try {\n      await workspaceApi.delete(targetId)\n      if (isStaleIdentity(generation)) return\n\n      if (targetId === activeWorkspaceId.value) {\n        // Sorted personal-first, so this is personal or the next team.\n        const fallback = workspaces.value.find((w) => w.id !== targetId)\n        prepareWorkflowWorkspaceTransition()\n        workspaceAuthStore.clearWorkspaceContext()\n        if (fallback) setLastWorkspaceId(fallback.id)\n        else clearLastWorkspaceId()\n        window.location.reload()\n        // Code after this won't run (page reloads)\n      } else {\n        // Deleted non-active workspace - just update local list\n        workspaces.value = workspaces.value.filter((w) => w.id !== targetId)\n        isDeleting.value = false\n      }\n    } catch (e) {\n      if (!isStaleIdentity(generation)) {\n        isDeleting.value = false\n      }\n      throw e\n    }\n  }\n\n  /**\n   * Rename a workspace. No reload needed.\n   */\n  async function renameWorkspace(\n    workspaceId: string,\n    newName: string\n  ): Promise<void> {\n    const generation = identityGeneration\n    const updated = await workspaceApi.update(workspaceId, { name: newName })\n    if (isStaleIdentity(generation)) return\n    updateWorkspace(workspaceId, { name: updated.name })\n  }\n\n  /**\n   * Update workspace name (convenience for current workspace).\n   */\n  async function updateWorkspaceName(name: string): Promise<void> {\n    if (!activeWorkspaceId.value) {\n      throw new Error('No active workspace')\n    }\n    await renameWorkspace(activeWorkspaceId.value, name)\n  }\n\n  async function leaveWorkspace(): Promise<void> {\n    const generation = identityGeneration\n    const current = activeWorkspace.value\n    if (!current) throw new Error('No active workspace')\n\n    const workspaceAuthStore = useWorkspaceAuthStore()\n\n    await workspaceApi.leave()\n    if (isStaleIdentity(generation)) return\n\n    const personal = workspaces.value.find(\n      (workspace) =>\n        workspace.type === 'personal' && workspace.id !== current.id\n    )\n    prepareWorkflowWorkspaceTransition()\n    workspaceAuthStore.clearWorkspaceContext()\n    if (personal) {\n      setLastWorkspaceId(personal.id)\n    } else {\n      clearLastWorkspaceId()\n    }\n    window.location.reload()\n    // Code after this won't run (page reloads)\n  }\n\n  let latestMembersRequest = 0\n\n  /**\n   * Fetch members for the current workspace.\n   */\n  async function fetchMembers(\n    params: ListMembersParams = {}\n  ): Promise<WorkspaceMember[]> {\n    const request = ++latestMembersRequest\n    const generation = identityGeneration\n    const workspaceId = activeWorkspaceId.value\n    if (!workspaceId) return []\n\n    const response = await workspaceApi.listMembers({\n      ...params,\n      limit: params.limit ?? 100\n    })\n    const members = response.members.map(mapApiMemberToWorkspaceMember)\n    if (\n      request === latestMembersRequest &&\n      !isStaleWorkspace(generation, workspaceId)\n    ) {\n      updateWorkspace(workspaceId, {\n        members,\n        membersLoaded: true,\n        totalMembers: response.pagination.total\n      })\n    }\n    return members\n  }\n\n  // Tracks which workspaces have already loaded their members so the\n  // lifecycle gate resolves without redundant or duplicate fetches.\n  const loadedMemberWorkspaceIds = new Set<string>()\n  let inFlightMembersRequest: {\n    generation: number\n    workspaceId: string\n  } | null = null\n\n  /**\n   * Load the active workspace's members once. No-ops for already-loaded\n   * workspaces and dedupes concurrent calls. A failed request is logged and\n   * leaves the workspace unloaded so a later call retries.\n   */\n  async function ensureMembersLoaded(): Promise<void> {\n    const workspaceId = activeWorkspaceId.value\n    const generation = identityGeneration\n    if (!workspaceId) return\n    if (loadedMemberWorkspaceIds.has(workspaceId)) return\n    if (\n      inFlightMembersRequest?.generation === generation &&\n      inFlightMembersRequest.workspaceId === workspaceId\n    ) {\n      return\n    }\n\n    const request = { generation, workspaceId }\n    inFlightMembersRequest = request\n    try {\n      await fetchMembers()\n      if (\n        !isStaleWorkspace(generation, workspaceId) &&\n        activeWorkspace.value?.membersLoaded\n      ) {\n        loadedMemberWorkspaceIds.add(workspaceId)\n      }\n    } catch (e) {\n      if (!isStaleIdentity(generation)) {\n        console.error('Failed to load workspace members', e)\n      }\n    } finally {\n      if (inFlightMembersRequest === request) {\n        inFlightMembersRequest = null\n      }\n    }\n  }\n\n  /**\n   * Remove a member from the current workspace.\n   */\n  async function removeMember(userId: string): Promise<void> {\n    const generation = identityGeneration\n    const workspaceId = activeWorkspaceId.value\n    if (!workspaceId) return\n\n    await workspaceApi.removeMember(userId)\n    if (isStaleWorkspace(generation, workspaceId)) {\n      return\n    }\n    const current = workspaces.value.find((w) => w.id === workspaceId)\n    if (current) {\n      updateWorkspace(workspaceId, {\n        members: current.members.filter((m) => m.id !== userId),\n        totalMembers:\n          current.totalMembers === undefined\n            ? undefined\n            : Math.max(0, current.totalMembers - 1)\n      })\n    }\n  }\n\n  /**\n   * Change a member's role in the current workspace.\n   */\n  async function changeMemberRole(\n    userId: string,\n    role: WorkspaceMember['role']\n  ): Promise<void> {\n    const generation = identityGeneration\n    const workspaceId = activeWorkspaceId.value\n    if (!workspaceId) return\n    if (\n      activeWorkspace.value?.type === 'personal' &&\n      userId === originalOwnerId.value\n    ) {\n      throw new Error(\"Cannot change the workspace creator's role\")\n    }\n    // Only the role changes; merge it onto the existing row rather than trusting\n    // the PATCH response to echo a full Member (a 204/partial body would\n    // otherwise drop joined_at / is_original_owner).\n    await workspaceApi.updateMemberRole(userId, role)\n    if (isStaleWorkspace(generation, workspaceId)) {\n      return\n    }\n    const current = workspaces.value.find((w) => w.id === workspaceId)\n    if (current) {\n      updateWorkspace(workspaceId, {\n        members: current.members.map((m) =>\n          m.id === userId ? { ...m, role } : m\n        )\n      })\n    }\n  }\n\n  /**\n   * Set or clear a member's monthly credit limit. Local-only until backend\n   * persistence lands in FE-1278; `null` removes the cap.\n   */\n  function setMemberCreditLimit(userId: string, limit: number | null): void {\n    const current = activeWorkspace.value\n    if (!current) return\n    updateActiveWorkspace({\n      members: current.members.map((m) =>\n        m.id === userId ? { ...m, monthlyCreditLimit: limit } : m\n      )\n    })\n  }\n\n  let latestInvitesRequest = 0\n\n  /**\n   * Fetch pending invites for the current workspace.\n   */\n  async function fetchPendingInvites(): Promise<WorkspacePendingInvite[]> {\n    const request = ++latestInvitesRequest\n    const generation = identityGeneration\n    const workspaceId = activeWorkspaceId.value\n    if (!workspaceId) return []\n\n    const response = await workspaceApi.listInvites()\n    const invites = response.invites.map(mapApiInviteToPendingInvite)\n    if (\n      request === latestInvitesRequest &&\n      !isStaleWorkspace(generation, workspaceId)\n    ) {\n      updateWorkspace(workspaceId, {\n        pendingInvites: invites,\n        pendingInvitesLoaded: true\n      })\n    }\n    return invites\n  }\n\n  /**\n   * Create an invite for the current workspace.\n   */\n  async function createInvite(email: string): Promise<WorkspacePendingInvite> {\n    const generation = identityGeneration\n    const workspaceId = activeWorkspaceId.value\n    const response = await workspaceApi.createInvite({ email })\n    const invite = mapApiInviteToPendingInvite(response)\n\n    if (!workspaceId || isStaleWorkspace(generation, workspaceId)) {\n      return invite\n    }\n    const current = workspaces.value.find((w) => w.id === workspaceId)\n    if (current) {\n      updateWorkspace(workspaceId, {\n        pendingInvites: [...current.pendingInvites, invite]\n      })\n    }\n\n    return invite\n  }\n\n  /**\n   * Revoke a pending invite.\n   */\n  async function revokeInvite(inviteId: string): Promise<void> {\n    const generation = identityGeneration\n    const workspaceId = activeWorkspaceId.value\n    await workspaceApi.revokeInvite(inviteId)\n    if (!workspaceId || isStaleWorkspace(generation, workspaceId)) {\n      return\n    }\n    const current = workspaces.value.find((w) => w.id === workspaceId)\n    if (current) {\n      updateWorkspace(workspaceId, {\n        pendingInvites: current.pendingInvites.filter((i) => i.id !== inviteId)\n      })\n    }\n  }\n\n  const resendingInviteIds = new Set<string>()\n\n  async function resendInvite(\n    inviteId: string\n  ): Promise<WorkspacePendingInvite> {\n    const generation = identityGeneration\n    const resendKey = `${generation}:${inviteId}`\n    const workspace = activeWorkspace.value\n    const invite = workspace?.pendingInvites.find(\n      (invite) => invite.id === inviteId\n    )\n    if (resendingInviteIds.has(resendKey)) {\n      console.error('Invite resend already in progress')\n      if (invite) return invite\n    }\n    if (!workspace || !invite) {\n      throw new Error('Invite not found')\n    }\n    resendingInviteIds.add(resendKey)\n    try {\n      const refreshed = mapApiInviteToPendingInvite(\n        await workspaceApi.resendInvite(inviteId)\n      )\n      if (isStaleIdentity(generation)) return refreshed\n      const currentWorkspace = workspaces.value.find(\n        (candidate) => candidate.id === workspace.id\n      )\n      if (currentWorkspace) {\n        updateWorkspace(workspace.id, {\n          pendingInvites: currentWorkspace